1	const std = @import("std");
2	const datatype = @import("datatype.zig");
3	const array_ref_mod = @import("array/array_ref.zig");
4	const array_data = @import("array/array_data.zig");
5	const array_mod = @import("array/array.zig");
6	const buffer = @import("buffer.zig");
7	const bitmap = @import("bitmap.zig");
8	
9	pub const DataType = datatype.DataType;
10	pub const ArrayRef = array_ref_mod.ArrayRef;
11	pub const ArrayData = array_data.ArrayData;
12	
13	pub const ConcatArrayError = error{ OutOfMemory, InvalidInput, UnsupportedType };
14	pub const Error = ConcatArrayError || array_data.ValidationError;
15	
16	pub fn concatArrayRefs(
17	    allocator: std.mem.Allocator,
18	    data_type: DataType,
19	    parts: []const ArrayRef,
20	) Error!ArrayRef {
21	    if (parts.len == 0) return error.InvalidInput;
22	
23	    for (parts) |part| {
24	        if (!datatype.dataTypeEql(part.data().data_type, data_type)) return error.InvalidInput;
25	    }
26	
27	    var acc = try parts[0].slice(0, 0);
28	    errdefer acc.release();
29	
30	    for (parts) |part| {
31	        const merged = try concatTwoArrayRefs(allocator, acc, part);
32	        acc.release();
33	        acc = merged;
34	    }
35	
36	    return acc;
37	}
38	
39	fn concatTwoArrayRefs(
40	    allocator: std.mem.Allocator,
41	    left: ArrayRef,
42	    right: ArrayRef,
43	) Error!ArrayRef {
44	    if (!datatype.dataTypeEql(left.data().data_type, right.data().data_type)) return error.InvalidInput;
45	
46	    const dt = left.data().data_type;
47	    const layout_dt = storageDataType(dt);
48	    var merged_storage = try switch (layout_dt) {
49	        .null => try concatNullArray(allocator, layout_dt, left.data(), right.data()),
50	        .bool => try concatBooleanArray(allocator, layout_dt, left.data(), right.data()),
51	        .uint8, .int8 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 1),
52	        .uint16, .int16, .half_float => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 2),
53	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 4),
54	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 8),
55	        .decimal128, .interval_month_day_nano => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 16),
56	        .decimal256 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 32),
57	        .fixed_size_binary => |fsb| blk: {
58	            const byte_width = std.math.cast(usize, fsb.byte_width) orelse return error.InvalidInput;
59	            break :blk try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), byte_width);
60	        },
61	        .string, .binary => try concatVariableBinaryArrayI32(allocator, layout_dt, left.data(), right.data()),
62	        .large_string, .large_binary => try concatVariableBinaryArrayI64(allocator, layout_dt, left.data(), right.data()),
63	        .string_view => try concatStringViewArray(allocator, left.data(), right.data()),
64	        .binary_view => try concatBinaryViewArray(allocator, left.data(), right.data()),
65	        .list, .map => try concatListLikeArrayI32(allocator, layout_dt, left.data(), right.data()),
66	        .large_list => try concatListLikeArrayI64(allocator, layout_dt, left.data(), right.data()),
67	        .fixed_size_list => try concatFixedSizeListArray(allocator, layout_dt, left.data(), right.data()),
68	        .struct_ => try concatStructArray(allocator, layout_dt, left.data(), right.data()),
69	        else => error.UnsupportedType,
70	    };
71	
72	    if (datatype.dataTypeEql(dt, layout_dt)) return merged_storage;
73	    const retagged = try retagArrayRefDataType(allocator, merged_storage, dt);
74	    merged_storage.release();
75	    return retagged;
76	}
77	
78	fn storageDataType(dt: DataType) DataType {
79	    return switch (dt) {
80	        .extension => |ext| storageDataType(ext.storage_type.*),
81	        else => dt,
82	    };
83	}
84	
85	fn retagArrayRefDataType(allocator: std.mem.Allocator, src: ArrayRef, out_dt: DataType) error{OutOfMemory}!ArrayRef {
86	    var out = src.data().*;
87	    out.data_type = out_dt;
88	    return ArrayRef.fromBorrowed(allocator, out);
89	}
90	
91	fn concatListLikeArrayI32(
92	    allocator: std.mem.Allocator,
93	    dt: DataType,
94	    left: *const ArrayData,
95	    right: *const ArrayData,
96	) Error!ArrayRef {
97	    try requireBufferCount(left, 2);
98	    try requireBufferCount(right, 2);
99	    if (left.children.len != 1 or right.children.len != 1) return error.InvalidInput;
100	
101	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
102	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
103	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
104	    errdefer if (!validity.isEmpty()) {
105	        var owned = validity;
106	        owned.release();
107	    };
108	
109	    const left_offsets = left.buffers[1].typedSlice(i32) catch return error.InvalidInput;
110	    const right_offsets = right.buffers[1].typedSlice(i32) catch return error.InvalidInput;
111	
112	    const left_last_index = std.math.add(usize, left.offset, left.length) catch return error.InvalidInput;
113	    const right_last_index = std.math.add(usize, right.offset, right.length) catch return error.InvalidInput;
114	    if (left_last_index >= left_offsets.len or right_last_index >= right_offsets.len) return error.InvalidInput;
115	
116	    const left_base = left_offsets[left.offset];
117	    const left_last = left_offsets[left_last_index];
118	    const right_base = right_offsets[right.offset];
119	    const right_last = right_offsets[right_last_index];
120	    if (left_base < 0 or left_last < left_base or right_base < 0 or right_last < right_base) return error.InvalidInput;
121	
122	    const offsets_len = std.math.add(usize, total_len, 1) catch return error.InvalidInput;
123	    var offsets_owned = try buffer.OwnedBuffer.init(allocator, offsets_len * @sizeOf(i32));
124	    var out_offsets = offsets_owned.typedSlice(i32)[0..offsets_len];
125	    out_offsets[0] = 0;
126	
127	    var i: usize = 0;
128	    while (i < left.length) : (i += 1) {
129	        const rel = std.math.sub(i32, left_offsets[left.offset + i + 1], left_base) catch return error.InvalidInput;
130	        out_offsets[i + 1] = rel;
131	    }
132	    const left_prefix = out_offsets[left.length];
133	    while (i < total_len) : (i += 1) {
134	        const right_i = i - left.length;
135	        const rel = std.math.sub(i32, right_offsets[right.offset + right_i + 1], right_base) catch return error.InvalidInput;
136	        out_offsets[i + 1] = std.math.add(i32, left_prefix, rel) catch return error.InvalidInput;
137	    }
138	    var offsets = try offsets_owned.toShared(offsets_len * @sizeOf(i32));
139	    errdefer offsets.release();
140	
141	    const left_child_start = std.math.cast(usize, left_base) orelse return error.InvalidInput;
142	    const left_child_end = std.math.cast(usize, left_last) orelse return error.InvalidInput;
143	    const right_child_start = std.math.cast(usize, right_base) orelse return error.InvalidInput;
144	    const right_child_end = std.math.cast(usize, right_last) orelse return error.InvalidInput;
145	    const left_child_len = std.math.sub(usize, left_child_end, left_child_start) catch return error.InvalidInput;
146	    const right_child_len = std.math.sub(usize, right_child_end, right_child_start) catch return error.InvalidInput;
147	
148	    var left_child = try left.children[0].slice(left_child_start, left_child_len);
149	    defer left_child.release();
150	    var right_child = try right.children[0].slice(right_child_start, right_child_len);
151	    defer right_child.release();
152	    var merged_child = try concatTwoArrayRefs(allocator, left_child, right_child);
153	    errdefer merged_child.release();
154	
155	    const buffers = try allocator.alloc(array_data.SharedBuffer, 2);
156	    errdefer allocator.free(buffers);
157	    buffers[0] = validity;
158	    buffers[1] = offsets;
159	    const children = try allocator.alloc(ArrayRef, 1);
160	    errdefer allocator.free(children);
161	    children[0] = merged_child;
162	
163	    const data = ArrayData{
164	        .data_type = dt,
165	        .length = total_len,
166	        .null_count = null_count,
167	        .buffers = buffers,
168	        .children = children,
169	        .dictionary = null,
170	    };
171	    try data.validateLayout();
172	    return ArrayRef.fromOwnedUnsafe(allocator, data);
173	}
174	
