176	    allocator: std.mem.Allocator,
177	    dt: DataType,
178	    left: *const ArrayData,
179	    right: *const ArrayData,
180	) Error!ArrayRef {
181	    try requireBufferCount(left, 2);
182	    try requireBufferCount(right, 2);
183	    if (left.children.len != 1 or right.children.len != 1) return error.InvalidInput;
184	
185	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
186	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
187	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
188	    errdefer if (!validity.isEmpty()) {
