220	        out_offsets[i + 1] = std.math.add(i64, left_prefix, rel) catch return error.InvalidInput;
221	    }
222	    var offsets = try offsets_owned.toShared(offsets_len * @sizeOf(i64));
223	    errdefer offsets.release();
224	
225	    const left_child_start = std.math.cast(usize, left_base) orelse return error.InvalidInput;
226	    const left_child_end = std.math.cast(usize, left_last) orelse return error.InvalidInput;
227	    const right_child_start = std.math.cast(usize, right_base) orelse return error.InvalidInput;
228	    const right_child_end = std.math.cast(usize, right_last) orelse return error.InvalidInput;
229	    const left_child_len = std.math.sub(usize, left_child_end, left_child_start) catch return error.InvalidInput;
230	    const right_child_len = std.math.sub(usize, right_child_end, right_child_start) catch return error.InvalidInput;
231	
232	    var left_child = try left.children[0].slice(left_child_start, left_child_len);
233	    defer left_child.release();
234	    var right_child = try right.children[0].slice(right_child_start, right_child_len);
235	    defer right_child.release();
236	    var merged_child = try concatTwoArrayRefs(allocator, left_child, right_child);
237	    errdefer merged_child.release();
238	
239	    const buffers = try allocator.alloc(array_data.SharedBuffer, 2);
240	    errdefer allocator.free(buffers);
241	    buffers[0] = validity;
242	    buffers[1] = offsets;
243	    const children = try allocator.alloc(ArrayRef, 1);
244	    errdefer allocator.free(children);
245	    children[0] = merged_child;
246	
247	    const data = ArrayData{
248	        .data_type = dt,
249	        .length = total_len,
250	        .null_count = null_count,
251	        .buffers = buffers,
252	        .children = children,
253	        .dictionary = null,
254	    };
255	    try data.validateLayout();
