259	fn concatFixedSizeListArray(
260	    allocator: std.mem.Allocator,
261	    dt: DataType,
262	    left: *const ArrayData,
263	    right: *const ArrayData,
264	) Error!ArrayRef {
265	    try requireBufferCount(left, 1);
266	    try requireBufferCount(right, 1);
267	    if (left.children.len != 1 or right.children.len != 1) return error.InvalidInput;
268	    const list_size = std.math.cast(usize, dt.fixed_size_list.list_size) orelse return error.InvalidInput;
269	    if (list_size == 0) return error.InvalidInput;
270	
271	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
272	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
273	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
274	    errdefer if (!validity.isEmpty()) {
275	        var owned = validity;
276	        owned.release();
277	    };
278	
279	    const left_child_start = std.math.mul(usize, left.offset, list_size) catch return error.InvalidInput;
280	    const left_child_len = std.math.mul(usize, left.length, list_size) catch return error.InvalidInput;
281	    const right_child_start = std.math.mul(usize, right.offset, list_size) catch return error.InvalidInput;
282	    const right_child_len = std.math.mul(usize, right.length, list_size) catch return error.InvalidInput;
283	
284	    var left_child = try left.children[0].slice(left_child_start, left_child_len);
285	    defer left_child.release();
286	    var right_child = try right.children[0].slice(right_child_start, right_child_len);
287	    defer right_child.release();
288	    var merged_child = try concatTwoArrayRefs(allocator, left_child, right_child);
289	    errdefer merged_child.release();
290	
291	    const buffers = try allocator.alloc(array_data.SharedBuffer, 1);
292	    errdefer allocator.free(buffers);
293	    buffers[0] = validity;
294	    const children = try allocator.alloc(ArrayRef, 1);
295	    errdefer allocator.free(children);
296	    children[0] = merged_child;
297	
298	    const data = ArrayData{
299	        .data_type = dt,
300	        .length = total_len,
301	        .null_count = null_count,
302	        .buffers = buffers,
303	        .children = children,
304	        .dictionary = null,
305	    };
306	    try data.validateLayout();
307	    return ArrayRef.fromOwnedUnsafe(allocator, data);
308	}
309	
310	fn concatStructArray(
311	    allocator: std.mem.Allocator,
312	    dt: DataType,
313	    left: *const ArrayData,
314	    right: *const ArrayData,
315	) Error!ArrayRef {
316	    try requireBufferCount(left, 1);
317	    try requireBufferCount(right, 1);
318	    if (left.children.len != dt.struct_.fields.len or right.children.len != dt.struct_.fields.len) return error.InvalidInput;
319	
320	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
321	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
322	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
323	    errdefer if (!validity.isEmpty()) {
324	        var owned = validity;
325	        owned.release();
326	    };
327	
328	    const children = try allocator.alloc(ArrayRef, dt.struct_.fields.len);
329	    var child_count: usize = 0;
330	    errdefer {
331	        var i: usize = 0;
332	        while (i < child_count) : (i += 1) {
333	            var owned = children[i];
334	            owned.release();
335	        }
336	        allocator.free(children);
337	    }
338	    for (left.children, right.children, 0..) |left_child_ref, right_child_ref, idx| {
339	        var left_child = try sliceStructChildRef(left_child_ref, left);
340	        defer left_child.release();
341	        var right_child = try sliceStructChildRef(right_child_ref, right);
342	        defer right_child.release();
343	        children[idx] = try concatTwoArrayRefs(allocator, left_child, right_child);
344	        child_count += 1;
345	    }
346	
347	    const buffers = try allocator.alloc(array_data.SharedBuffer, 1);
348	    errdefer allocator.free(buffers);
349	    buffers[0] = validity;
350	
351	    const data = ArrayData{
352	        .data_type = dt,
353	        .length = total_len,
354	        .null_count = null_count,
355	        .buffers = buffers,
356	        .children = children,
357	        .dictionary = null,
358	    };
359	    try data.validateLayout();
360	    return ArrayRef.fromOwnedUnsafe(allocator, data);
361	}
362	
363	fn viewDataCapacityHint(data: *const ArrayData) usize {
364	    if (data.buffers.len >= 3) return data.buffers[2].len();
365	    return 0;
366	}
367	
368	fn concatStringViewArray(
369	    allocator: std.mem.Allocator,
370	    left: *const ArrayData,
371	    right: *const ArrayData,
372	) Error!ArrayRef {
373	    try left.validateLayout();
374	    try right.validateLayout();
375	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
376	    const data_capacity = std.math.add(usize, viewDataCapacityHint(left), viewDataCapacityHint(right)) catch return error.InvalidInput;
377	
378	    var builder = try array_mod.StringViewBuilder.init(allocator, total_len, data_capacity);
379	    defer builder.deinit();
380	
381	    const left_view = array_mod.StringViewArray{ .data = left };
382	    var i: usize = 0;
383	    while (i < left.length) : (i += 1) {
384	        if (left_view.isNull(i)) {
385	            builder.appendNull() catch |err| return mapViewBuilderError(err);
386	        } else {
387	            const value = left_view.value(i) catch return error.InvalidInput;
388	            builder.append(value) catch |err| return mapViewBuilderError(err);
389	        }
390	    }
391	
392	    const right_view = array_mod.StringViewArray{ .data = right };
393	    i = 0;
394	    while (i < right.length) : (i += 1) {
395	        if (right_view.isNull(i)) {
396	            builder.appendNull() catch |err| return mapViewBuilderError(err);
397	        } else {
398	            const value = right_view.value(i) catch return error.InvalidInput;
399	            builder.append(value) catch |err| return mapViewBuilderError(err);
400	        }
401	    }
402	
