410	    allocator: std.mem.Allocator,
411	    left: *const ArrayData,
412	    right: *const ArrayData,
413	) Error!ArrayRef {
414	    try left.validateLayout();
415	    try right.validateLayout();
416	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
417	    const data_capacity = std.math.add(usize, viewDataCapacityHint(left), viewDataCapacityHint(right)) catch return error.InvalidInput;
418	
