420	    defer builder.deinit();
421	
422	    const left_view = array_mod.BinaryViewArray{ .data = left };
423	    var i: usize = 0;
424	    while (i < left.length) : (i += 1) {
425	        if (left_view.isNull(i)) {
426	            builder.appendNull() catch |err| return mapViewBuilderError(err);
427	        } else {
428	            const value = left_view.value(i) catch return error.InvalidInput;
429	            builder.append(value) catch |err| return mapViewBuilderError(err);
430	        }
431	    }
432	
433	    const right_view = array_mod.BinaryViewArray{ .data = right };
434	    i = 0;
435	    while (i < right.length) : (i += 1) {
436	        if (right_view.isNull(i)) {
