438	        } else {
439	            const value = right_view.value(i) catch return error.InvalidInput;
440	            builder.append(value) catch |err| return mapViewBuilderError(err);
441	        }
442	    }
443	
444	    var out = builder.finish() catch |err| return mapViewBuilderError(err);
