457	fn sliceStructChildRef(child_ref: ArrayRef, parent: *const ArrayData) Error!ArrayRef {
458	    const child_len = child_ref.data().length;
459	    const required_end = std.math.add(usize, parent.offset, parent.length) catch return error.InvalidInput;
460	
461	    if (required_end <= child_len) {
462	        return child_ref.slice(parent.offset, parent.length);
463	    }
464	    if (parent.length <= child_len) {
465	        // Struct children coming from ArrayRef.slice() are already aligned to parent rows.
466	        return child_ref.slice(0, parent.length);
467	    }
468	    return error.InvalidInput;
