5	// Return the number of bytes required to store the requested bit count.
6	//
7	// Cases:
8	// - byteLength(0) == 0
9	// - byteLength(1) == 1
10	// - byteLength(7) == 1
11	// - byteLength(8) == 1
12	// - byteLength(9) == 2
13	// - byteLength(63) == 8
14	// - byteLength(64) == 8
15	// - byteLength(65) == 9
16	pub fn byteLength(bit_length: usize) usize {
17	    return (bit_length + 7) >> 3;
18	}
