51	// Clear a single bit in-place using Arrow's least-significant-bit-first bit order.
52	// Cases:
53	// - data = { 0b1111_1111 }, clearBit(data, 0) => { 0b1111_1110 }
54	// - data = { 0b1111_1111 }, clearBit(data, 7) => { 0b0111_1111 }
55	// - data = { 0b1111_1111, 0b1111_1111 }, clearBit(data, 9) => { 0b1111_1111, 0b1111_1101 }
56	pub fn clearBit(data: []u8, bit_index: usize) void {
57	    data[bit_index >> 3] &= ~bitMask(bit_index);
58	}
