69	// Number of bytes per SIMD lane group for the vectorised popcount path.
70	// 16 bytes == 128 bits (SSE2 / NEON tier).  Deliberately not 32 to work
71	// around a Zig 0.15.1 x86_64 codegen bug: the 32-lane path requires a
72	// VPMOVZXBD ymm,m128 encoding that the 0.15.1 backend cannot emit
73	// ("no encoding found for: none vpmovzxbd ymm m128 none none").
74	// With 16 lanes the maximum per-chunk lane sum is 16*8 = 128 ≤ u8::MAX,
75	// so no lane-widening before @reduce is needed, avoiding the problematic
76	// instruction entirely.  Performance is still 4-8× over the scalar loop.
77	const POPCOUNT_SIMD_LANES = 16;
78	
79	// Count set bits across the logical length, ignoring padding bits.
80	//
81	// Uses a @Vector SIMD loop for the bulk of the work so that the compiler can
82	// emit vectorised popcount instructions (VPOPCNTB / NEON VCNT).  A scalar
83	// tail handles the remaining bytes and the final partial byte.
84	pub fn countSetBit(data: []const u8, bit_len: usize) usize {
85	    if (bit_len == 0) return 0;
86	
87	    const full_bytes = bit_len >> 3;
88	    const remainder = bit_len & 7;
89	
90	    var count: usize = 0;
91	    var offset: usize = 0;
92	
93	    // SIMD bulk: POPCOUNT_SIMD_LANES bytes per iteration.
94	    // @popCount on a @Vector yields per-lane bit counts (each 0..8).
95	    // With 16 lanes the maximum aggregate is 16*8 = 128 ≤ u8::MAX,
96	    // so @reduce returns u8 without wrapping — no lane-widening needed.
97	    const simd_end = (full_bytes / POPCOUNT_SIMD_LANES) * POPCOUNT_SIMD_LANES;
98	    while (offset < simd_end) : (offset += POPCOUNT_SIMD_LANES) {
99	        const vec: @Vector(POPCOUNT_SIMD_LANES, u8) = data[offset..][0..POPCOUNT_SIMD_LANES].*;
100	        const lane_counts: @Vector(POPCOUNT_SIMD_LANES, u8) = @popCount(vec);
101	        count += @reduce(.Add, lane_counts);
102	    }
103	
104	    // Scalar tail for remaining full bytes.
105	    while (offset < full_bytes) : (offset += 1) {
106	        count += @popCount(data[offset]);
107	    }
108	
109	    // Partial final byte: mask off padding bits before counting.
110	    if (remainder > 0) {
111	        const last_byte = data[full_bytes];
112	        const mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
113	        count += @popCount(last_byte & mask);
114	    }
115	
116	    return count;
117	}
