165	// Count unset bits in the half-open range [start_bit, end_bit).
166	pub fn countUnsetBitsInRange(data: []const u8, start_bit: usize, end_bit: usize) usize {
167	    if (start_bit >= end_bit) return 0;
168	    return (end_bit - start_bit) - countSetBitsInRange(data, start_bit, end_bit);
169	}
