184	pub const ValidityBitmap = struct {
185	    data: []const u8,
186	    bit_len: usize,
187	
188	    const Error = error{IndexOutOfBounds};
189	
190	    // Build a validity bitmap view from a buffer and logical length.
191	    pub fn fromBuffer(buf: SharedBuffer, bit_len: usize) ValidityBitmap {
192	        return .{ .data = buf.data, .bit_len = bit_len };
193	    }
194	    // Read the validity bit for an index.
195	    pub inline fn isValid(self: ValidityBitmap, i: usize) Error!bool {
196	        if (i >= self.bit_len) return Error.IndexOutOfBounds;
197	        return bitIsSet(self.data, i);
198	    }
