200	    // Invert the validity bit for convenience.
201	    pub inline fn isNull(self: ValidityBitmap, i: usize) Error!bool {
202	        return !(try self.isValid(i));
203	    }
204	    // Count valid bits in the logical range.
205	    pub fn countValid(self: ValidityBitmap) usize {
206	        return countSetBit(self.data, self.bit_len);
207	    }
208	    // Count null bits in the logical range.
209	    pub fn countNulls(self: ValidityBitmap) usize {
210	        return self.bit_len - self.countValid();
211	    }
212	};
