39	fn concatTwoArrayRefs(
40	    allocator: std.mem.Allocator,
41	    left: ArrayRef,
42	    right: ArrayRef,
43	) Error!ArrayRef {
44	    if (!datatype.dataTypeEql(left.data().data_type, right.data().data_type)) return error.InvalidInput;
45	
46	    const dt = left.data().data_type;
47	    const layout_dt = storageDataType(dt);
48	    var merged_storage = try switch (layout_dt) {
49	        .null => try concatNullArray(allocator, layout_dt, left.data(), right.data()),
50	        .bool => try concatBooleanArray(allocator, layout_dt, left.data(), right.data()),
51	        .uint8, .int8 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 1),
52	        .uint16, .int16, .half_float => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 2),
53	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 4),
54	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 8),
55	        .decimal128, .interval_month_day_nano => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 16),
56	        .decimal256 => try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), 32),
57	        .fixed_size_binary => |fsb| blk: {
58	            const byte_width = std.math.cast(usize, fsb.byte_width) orelse return error.InvalidInput;
59	            break :blk try concatFixedWidthArray(allocator, layout_dt, left.data(), right.data(), byte_width);
60	        },
61	        .string, .binary => try concatVariableBinaryArrayI32(allocator, layout_dt, left.data(), right.data()),
62	        .large_string, .large_binary => try concatVariableBinaryArrayI64(allocator, layout_dt, left.data(), right.data()),
63	        .string_view => try concatStringViewArray(allocator, left.data(), right.data()),
64	        .binary_view => try concatBinaryViewArray(allocator, left.data(), right.data()),
65	        .list, .map => try concatListLikeArrayI32(allocator, layout_dt, left.data(), right.data()),
66	        .large_list => try concatListLikeArrayI64(allocator, layout_dt, left.data(), right.data()),
67	        .fixed_size_list => try concatFixedSizeListArray(allocator, layout_dt, left.data(), right.data()),
68	        .struct_ => try concatStructArray(allocator, layout_dt, left.data(), right.data()),
