91	fn concatListLikeArrayI32(
92	    allocator: std.mem.Allocator,
93	    dt: DataType,
94	    left: *const ArrayData,
95	    right: *const ArrayData,
96	) Error!ArrayRef {
97	    try requireBufferCount(left, 2);
98	    try requireBufferCount(right, 2);
99	    if (left.children.len != 1 or right.children.len != 1) return error.InvalidInput;
100	
101	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
102	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
103	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
104	    errdefer if (!validity.isEmpty()) {
105	        var owned = validity;
106	        owned.release();
107	    };
108	
109	    const left_offsets = left.buffers[1].typedSlice(i32) catch return error.InvalidInput;
110	    const right_offsets = right.buffers[1].typedSlice(i32) catch return error.InvalidInput;
111	
112	    const left_last_index = std.math.add(usize, left.offset, left.length) catch return error.InvalidInput;
113	    const right_last_index = std.math.add(usize, right.offset, right.length) catch return error.InvalidInput;
114	    if (left_last_index >= left_offsets.len or right_last_index >= right_offsets.len) return error.InvalidInput;
115	
116	    const left_base = left_offsets[left.offset];
117	    const left_last = left_offsets[left_last_index];
118	    const right_base = right_offsets[right.offset];
119	    const right_last = right_offsets[right_last_index];
120	    if (left_base < 0 or left_last < left_base or right_base < 0 or right_last < right_base) return error.InvalidInput;
121	
122	    const offsets_len = std.math.add(usize, total_len, 1) catch return error.InvalidInput;
123	    var offsets_owned = try buffer.OwnedBuffer.init(allocator, offsets_len * @sizeOf(i32));
124	    var out_offsets = offsets_owned.typedSlice(i32)[0..offsets_len];
125	    out_offsets[0] = 0;
126	
127	    var i: usize = 0;
128	    while (i < left.length) : (i += 1) {
129	        const rel = std.math.sub(i32, left_offsets[left.offset + i + 1], left_base) catch return error.InvalidInput;
130	        out_offsets[i + 1] = rel;
131	    }
132	    const left_prefix = out_offsets[left.length];
133	    while (i < total_len) : (i += 1) {
134	        const right_i = i - left.length;
135	        const rel = std.math.sub(i32, right_offsets[right.offset + right_i + 1], right_base) catch return error.InvalidInput;
136	        out_offsets[i + 1] = std.math.add(i32, left_prefix, rel) catch return error.InvalidInput;
137	    }
138	    var offsets = try offsets_owned.toShared(offsets_len * @sizeOf(i32));
139	    errdefer offsets.release();
140	
141	    const left_child_start = std.math.cast(usize, left_base) orelse return error.InvalidInput;
142	    const left_child_end = std.math.cast(usize, left_last) orelse return error.InvalidInput;
143	    const right_child_start = std.math.cast(usize, right_base) orelse return error.InvalidInput;
144	    const right_child_end = std.math.cast(usize, right_last) orelse return error.InvalidInput;
145	    const left_child_len = std.math.sub(usize, left_child_end, left_child_start) catch return error.InvalidInput;
146	    const right_child_len = std.math.sub(usize, right_child_end, right_child_start) catch return error.InvalidInput;
147	
148	    var left_child = try left.children[0].slice(left_child_start, left_child_len);
149	    defer left_child.release();
150	    var right_child = try right.children[0].slice(right_child_start, right_child_len);
151	    defer right_child.release();
152	    var merged_child = try concatTwoArrayRefs(allocator, left_child, right_child);
153	    errdefer merged_child.release();
154	
155	    const buffers = try allocator.alloc(array_data.SharedBuffer, 2);
156	    errdefer allocator.free(buffers);
157	    buffers[0] = validity;
158	    buffers[1] = offsets;
159	    const children = try allocator.alloc(ArrayRef, 1);
160	    errdefer allocator.free(children);
161	    children[0] = merged_child;
162	
163	    const data = ArrayData{
164	        .data_type = dt,
165	        .length = total_len,
166	        .null_count = null_count,
167	        .buffers = buffers,
168	        .children = children,
169	        .dictionary = null,
170	    };
171	    try data.validateLayout();
172	    return ArrayRef.fromOwnedUnsafe(allocator, data);
173	}
