457	fn sliceStructChildRef(child_ref: ArrayRef, parent: *const ArrayData) Error!ArrayRef {
458	    const child_len = child_ref.data().length;
459	    const required_end = std.math.add(usize, parent.offset, parent.length) catch return error.InvalidInput;
