590	fn concatVariableBinaryArrayI32(
591	    allocator: std.mem.Allocator,
592	    dt: DataType,
593	    left: *const ArrayData,
594	    right: *const ArrayData,
595	) Error!ArrayRef {
596	    try requireBufferCount(left, 3);
597	    try requireBufferCount(right, 3);
598	
599	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
600	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
601	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
602	    errdefer if (!validity.isEmpty()) {
603	        var owned = validity;
604	        owned.release();
605	    };
606	
607	    const left_offsets = left.buffers[1].typedSlice(i32) catch return error.InvalidInput;
608	    const right_offsets = right.buffers[1].typedSlice(i32) catch return error.InvalidInput;
609	    const left_last_index = std.math.add(usize, left.offset, left.length) catch return error.InvalidInput;
610	    const right_last_index = std.math.add(usize, right.offset, right.length) catch return error.InvalidInput;
611	    if (left_last_index >= left_offsets.len or right_last_index >= right_offsets.len) return error.InvalidInput;
612	
613	    const left_start = std.math.cast(usize, left_offsets[left.offset]) orelse return error.InvalidInput;
614	    const left_end = std.math.cast(usize, left_offsets[left_last_index]) orelse return error.InvalidInput;
615	    const right_start = std.math.cast(usize, right_offsets[right.offset]) orelse return error.InvalidInput;
616	    const right_end = std.math.cast(usize, right_offsets[right_last_index]) orelse return error.InvalidInput;
617	    if (left_end < left_start or right_end < right_start) return error.InvalidInput;
618	    if (left_end > left.buffers[2].len() or right_end > right.buffers[2].len()) return error.InvalidInput;
619	
620	    const left_data_len = std.math.sub(usize, left_end, left_start) catch return error.InvalidInput;
621	    const right_data_len = std.math.sub(usize, right_end, right_start) catch return error.InvalidInput;
622	    const total_data_len = std.math.add(usize, left_data_len, right_data_len) catch return error.InvalidInput;
623	
624	    const offsets_len = std.math.add(usize, total_len, 1) catch return error.InvalidInput;
625	    var offsets_owned = try buffer.OwnedBuffer.init(allocator, offsets_len * @sizeOf(i32));
626	    var out_offsets = offsets_owned.typedSlice(i32)[0..offsets_len];
627	    out_offsets[0] = 0;
628	    var i: usize = 0;
629	    while (i < left.length) : (i += 1) {
630	        const cur = std.math.sub(i32, left_offsets[left.offset + i + 1], left_offsets[left.offset]) catch return error.InvalidInput;
631	        out_offsets[i + 1] = cur;
632	    }
633	    const left_prefix = out_offsets[left.length];
634	    while (i < total_len) : (i += 1) {
635	        const right_idx = i - left.length;
636	        const delta_off = std.math.sub(i32, right_offsets[right.offset + right_idx + 1], right_offsets[right.offset]) catch return error.InvalidInput;
637	        out_offsets[i + 1] = std.math.add(i32, left_prefix, delta_off) catch return error.InvalidInput;
638	    }
639	    var offsets = try offsets_owned.toShared(offsets_len * @sizeOf(i32));
640	    errdefer offsets.release();
641	
642	    var values_owned = try buffer.OwnedBuffer.init(allocator, total_data_len);
643	    if (left_data_len > 0) {
644	        @memcpy(values_owned.data[0..left_data_len], left.buffers[2].data[left_start..left_end]);
645	    }
646	    if (right_data_len > 0) {
647	        @memcpy(values_owned.data[left_data_len .. left_data_len + right_data_len], right.buffers[2].data[right_start..right_end]);
648	    }
649	    var values = try values_owned.toShared(total_data_len);
650	    errdefer values.release();
651	
652	    const buffers = try allocator.alloc(array_data.SharedBuffer, 3);
653	    errdefer allocator.free(buffers);
654	    buffers[0] = validity;
655	    buffers[1] = offsets;
656	    buffers[2] = values;
657	    const children = try allocator.alloc(ArrayRef, 0);
658	    errdefer allocator.free(children);
659	
660	    const data = ArrayData{
661	        .data_type = dt,
662	        .length = total_len,
663	        .null_count = null_count,
664	        .buffers = buffers,
665	        .children = children,
666	        .dictionary = null,
667	    };
668	    try data.validateLayout();
669	    return ArrayRef.fromOwnedUnsafe(allocator, data);
670	}
