5	// Return the number of bytes required to store the requested bit count.
6	//
7	// Cases:
8	// - byteLength(0) == 0
9	// - byteLength(1) == 1
10	// - byteLength(7) == 1
11	// - byteLength(8) == 1
12	// - byteLength(9) == 2
13	// - byteLength(63) == 8
14	// - byteLength(64) == 8
15	// - byteLength(65) == 9
16	pub fn byteLength(bit_length: usize) usize {
17	    return (bit_length + 7) >> 3;
18	}
19	
20	fn bitMask(bit_index: usize) u8 {
21	    // Cases (LSB-first, index wraps every 8 bits):
22	    // - bitMask(0) == 0b0000_0001
23	    // - bitMask(1) == 0b0000_0010
24	    // - bitMask(7) == 0b1000_0000
25	    // - bitMask(8) == 0b0000_0001
26	    // - bitMask(9) == 0b0000_0010
27	    return @as(u8, 1) << @as(u3, @intCast(bit_index & 7));
28	}
29	
30	// Read a single bit using Arrow's least-significant-bit-first order.
31	pub fn bitIsSet(data: []const u8, bit_index: usize) bool {
32	    // Cases:
33	    // - data = { 0b0000_0101 }, bitIsSet(data, 0) == true
34	    // - data = { 0b0000_0101 }, bitIsSet(data, 1) == false
35	    // - data = { 0b0000_0101 }, bitIsSet(data, 2) == true
36	    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 9) == true
37	    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 8) == false
38	    const byte = data[bit_index >> 3];
39	    return (byte & bitMask(bit_index)) != 0;
40	}
41	
42	// Set a single bit in-place using Arrow's least-significant-bit-first bit order.
43	// Cases:
44	// - data = { 0b0000_0000 }, setBit(data, 0) => { 0b0000_0001 }
45	// - data = { 0b0000_0000 }, setBit(data, 7) => { 0b1000_0000 }
46	// - data = { 0b0000_0000, 0b0000_0000 }, setBit(data, 9) => { 0b0000_0000, 0b0000_0010 }
47	pub fn setBit(data: []u8, bit_index: usize) void {
48	    data[bit_index >> 3] |= bitMask(bit_index);
49	}
50	
51	// Clear a single bit in-place using Arrow's least-significant-bit-first bit order.
52	// Cases:
53	// - data = { 0b1111_1111 }, clearBit(data, 0) => { 0b1111_1110 }
54	// - data = { 0b1111_1111 }, clearBit(data, 7) => { 0b0111_1111 }
55	// - data = { 0b1111_1111, 0b1111_1111 }, clearBit(data, 9) => { 0b1111_1111, 0b1111_1101 }
56	pub fn clearBit(data: []u8, bit_index: usize) void {
57	    data[bit_index >> 3] &= ~bitMask(bit_index);
58	}
59	
60	// Write a single bit in-place with a boolean value.
61	// Cases:
62	// - data = { 0b0000_0000 }, writeBit(data, 1, true) => { 0b0000_0010 }
63	// - data = { 0b0000_0010 }, writeBit(data, 1, false) => { 0b0000_0000 }
64	// - data = { 0b0000_0000, 0b0000_0000 }, writeBit(data, 9, true) => { 0b0000_0000, 0b0000_0010 }
65	pub fn writeBit(data: []u8, bit_index: usize, value: bool) void {
66	    if (value) setBit(data, bit_index) else clearBit(data, bit_index);
67	}
