171	fn clearTrailingBits(bytes: []u8, len: usize, valid: bool) void {
172	    if (len == 0 or bytes.len == 0) return;
173	
174	    const remainder = len & 7;
175	    if (remainder == 0) return;
176	
177	    const last = bytes.len - 1;
178	    const keep_mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
179	    bytes[last] &= keep_mask;
180	    if (valid) bytes[last] |= keep_mask;
181	}
