183	// Immutable Arrow validity bitmap view.
184	pub const ValidityBitmap = struct {
185	    data: []const u8,
186	    bit_len: usize,
187	
188	    const Error = error{IndexOutOfBounds};
189	
190	    // Build a validity bitmap view from a buffer and logical length.
191	    pub fn fromBuffer(buf: SharedBuffer, bit_len: usize) ValidityBitmap {
192	        return .{ .data = buf.data, .bit_len = bit_len };
193	    }
194	    // Read the validity bit for an index.
195	    pub inline fn isValid(self: ValidityBitmap, i: usize) Error!bool {
196	        if (i >= self.bit_len) return Error.IndexOutOfBounds;
197	        return bitIsSet(self.data, i);
198	    }
199	
200	    // Invert the validity bit for convenience.
201	    pub inline fn isNull(self: ValidityBitmap, i: usize) Error!bool {
202	        return !(try self.isValid(i));
203	    }
204	    // Count valid bits in the logical range.
205	    pub fn countValid(self: ValidityBitmap) usize {
206	        return countSetBit(self.data, self.bit_len);
207	    }
208	    // Count null bits in the logical range.
209	    pub fn countNulls(self: ValidityBitmap) usize {
210	        return self.bit_len - self.countValid();
211	    }
212	};
