230	    fn initFilled(allocator: std.mem.Allocator, bit_len: usize, valid: bool) !MutableValidityBitmap {
231	        const used_bytes = byteLength(bit_len);
232	        var buf = try OwnedBuffer.init(allocator, used_bytes);
233	        if (used_bytes > 0) {
234	            @memset(buf.data[0..used_bytes], if (valid) 0xFF else 0x00);
235	            clearTrailingBits(buf.data[0..used_bytes], bit_len, valid);
236	        }
237	
238	        return .{
239	            .buf = buf,
240	            .bit_len = bit_len,
241	        };
242	    }
