265	    // Mark the indexed value as null.
266	    pub fn setNull(self: *MutableValidityBitmap, index: usize) void {
267	        std.debug.assert(index < self.bit_len);
268	
269	        const byte_index = index / 8;
270	        const mask = bitMask(index);
271	        self.buf.data[byte_index] &= ~mask;
272	    }
