218	    fn validateOffsetsI32(offsets: []const i32, total_len: usize, data_len: usize) ValidationError!void {
219	        const needed_len = std.math.add(usize, total_len, 1) catch return error.InvalidOffsets;
220	        if (offsets.len < needed_len) return error.BufferTooSmall;
221	        var prev: i32 = offsets[0];
222	        if (prev < 0) return error.InvalidOffsets;
223	        var i: usize = 1;
224	        while (i < needed_len) : (i += 1) {
225	            const cur = offsets[i];
226	            if (cur < prev or cur < 0) return error.InvalidOffsets;
227	            prev = cur;
228	        }
229	        const prev_usize = std.math.cast(usize, prev) orelse return error.InvalidOffsets;
230	        if (prev_usize > data_len) return error.InvalidOffsets;
231	    }
