233	    // ListView offsets/sizes are per-element views into the child array.
234	    fn validateOffsetsSizesI32(offsets: []const i32, sizes: []const i32, total_len: usize, child_len: usize) ValidationError!void {
235	        if (offsets.len < total_len) return error.BufferTooSmall;
236	        if (sizes.len < total_len) return error.BufferTooSmall;
237	        var i: usize = 0;
238	        while (i < total_len) : (i += 1) {
239	            const off = offsets[i];
240	            const size = sizes[i];
241	            if (off < 0 or size < 0) return error.InvalidOffsets;
242	            const off_usize = std.math.cast(usize, off) orelse return error.InvalidOffsets;
243	            const size_usize = std.math.cast(usize, size) orelse return error.InvalidOffsets;
244	            const end = std.math.add(usize, off_usize, size_usize) catch return error.InvalidOffsets;
245	            if (end > child_len) return error.InvalidOffsets;
246	        }
247	    }
