264	    fn readU32Le(bytes: []const u8) u32 {
265	        std.debug.assert(bytes.len >= 4);
266	        return @as(u32, bytes[0]) |
267	            (@as(u32, bytes[1]) << 8) |
268	            (@as(u32, bytes[2]) << 16) |
269	            (@as(u32, bytes[3]) << 24);
270	    }
271	
272	    fn validateByteViews(view_bytes: []const u8, total_len: usize, variadic: []const SharedBuffer) ValidationError!void {
273	        if (view_bytes.len % 16 != 0) return error.InvalidOffsetBuffer;
274	        const view_count = view_bytes.len / 16;
275	        if (view_count < total_len) return error.BufferTooSmall;
276	
277	        var i: usize = 0;
278	        while (i < total_len) : (i += 1) {
279	            const start = i * 16;
280	            const view = view_bytes[start .. start + 16];
281	            const len_u32 = readU32Le(view[0..4]);
282	            const len = std.math.cast(usize, len_u32) orelse return error.InvalidOffsets;
283	
284	            if (len <= 12) {
285	                const pad_start = 4 + len;
286	                for (view[pad_start..16]) |b| {
287	                    if (b != 0) return error.InvalidOffsets;
288	                }
289	                continue;
290	            }
291	
292	            const buffer_index = std.math.cast(usize, readU32Le(view[8..12])) orelse return error.InvalidOffsets;
293	            if (buffer_index >= variadic.len) return error.InvalidOffsets;
294	
295	            const byte_offset = std.math.cast(usize, readU32Le(view[12..16])) orelse return error.InvalidOffsets;
296	            const end = std.math.add(usize, byte_offset, len) catch return error.InvalidOffsets;
297	            if (end > variadic[buffer_index].len()) return error.InvalidOffsets;
298	            if (!std.mem.eql(u8, view[4..8], variadic[buffer_index].data[byte_offset .. byte_offset + 4])) {
299	                return error.InvalidOffsets;
300	            }
301	        }
302	    }
