304	    // Run ends must be strictly increasing and cover the logical length.
305	    fn validateRunEndsSigned(comptime T: type, run_ends: []const T, total_len: usize) ValidationError!void {
306	        if (total_len == 0) {
307	            if (run_ends.len != 0) return error.InvalidOffsets;
308	            return;
309	        }
310	        if (run_ends.len == 0) return error.BufferTooSmall;
311	        var prev: i64 = 0;
312	        for (run_ends) |end| {
313	            const val: i64 = @intCast(end);
314	            if (val <= prev) return error.InvalidOffsets;
315	            prev = val;
316	        }
317	        const total_len_i64 = std.math.cast(i64, total_len) orelse return error.InvalidOffsets;
318	        if (prev < total_len_i64) return error.InvalidOffsets;
319	    }
320	
321	    fn validateRunEndsUnsigned(comptime T: type, run_ends: []const T, total_len: usize) ValidationError!void {
322	        if (total_len == 0) {
323	            if (run_ends.len != 0) return error.InvalidOffsets;
324	            return;
325	        }
326	        if (run_ends.len == 0) return error.BufferTooSmall;
327	        var prev: u64 = 0;
328	        for (run_ends) |end| {
329	            const val: u64 = @intCast(end);
330	            if (val <= prev) return error.InvalidOffsets;
331	            prev = val;
332	        }
333	        const total_len_u64 = std.math.cast(u64, total_len) orelse return error.InvalidOffsets;
334	        if (prev < total_len_u64) return error.InvalidOffsets;
335	    }
