337	    fn unionTypeIdToChildIndex(uni: datatype.UnionType, type_id: i8) ?usize {
338	        if (uni.type_ids.len == 0) {
339	            if (type_id < 0) return null;
340	            const index = std.math.cast(usize, type_id) orelse return null;
341	            return if (index < uni.fields.len) index else null;
342	        }
343	        if (uni.type_ids.len != uni.fields.len) return null;
344	        for (uni.type_ids, 0..) |configured_id, child_index| {
345	            if (configured_id == type_id) return child_index;
346	        }
347	        return null;
348	    }
349	
350	    fn validateUnionTypeIds(uni: datatype.UnionType, type_ids: []const i8, start: usize, end: usize) ValidationError!void {
351	        if (type_ids.len < end) return error.BufferTooSmall;
352	        var i = start;
353	        while (i < end) : (i += 1) {
354	            const type_id = type_ids[i];
355	            if (unionTypeIdToChildIndex(uni, type_id) == null) return error.InvalidOffsets;
356	        }
357	    }
358	
359	    fn validateDenseUnionOffsets(
360	        uni: datatype.UnionType,
361	        type_ids: []const i8,
362	        offsets: []const i32,
363	        children: []const ArrayRef,
364	        start: usize,
365	        end: usize,
366	    ) ValidationError!void {
367	        if (offsets.len < end) return error.BufferTooSmall;
368	        var i = start;
369	        while (i < end) : (i += 1) {
370	            const child_index = unionTypeIdToChildIndex(uni, type_ids[i]) orelse return error.InvalidOffsets;
371	            const off = offsets[i];
372	            if (off < 0) return error.InvalidOffsets;
373	            const child_data = children[child_index].data();
374	            const child_total = std.math.add(usize, child_data.length, child_data.offset) catch return error.InvalidOffsets;
375	            const off_usize = std.math.cast(usize, off) orelse return error.InvalidOffsets;
376	            if (off_usize >= child_total) return error.InvalidOffsets;
377	        }
378	    }
