380	    fn childCoversRange(child_data: *const ArrayData, end: usize) ValidationError!void {
381	        const child_total = std.math.add(usize, child_data.offset, child_data.length) catch return error.InvalidChildren;
382	        if (child_total < end) return error.InvalidChildren;
383	    }
