385	    fn validateStructChildren(self: Self, fields: []const datatype.Field, end: usize) ValidationError!void {
386	        if (self.children.len != fields.len) return error.InvalidChildren;
387	        for (fields, 0..) |field, i| {
388	            const child_data = self.children[i].data();
389	            if (!child_data.data_type.eql(field.data_type.*)) return error.InvalidChildren;
390	            try childCoversRange(child_data, end);
391	        }
392	    }
