394	    fn validateMapChild(self: Self, map_type: datatype.MapType) ValidationError!void {
395	        if (self.children.len != 1) return error.InvalidChildren;
396	        const entries_data = self.children[0].data();
397	        if (map_type.entries_type) |entries_type| {
398	            if (!entries_data.data_type.eql(entries_type.*)) return error.InvalidChildren;
399	            return;
400	        }
401	
402	        const entries_fields = [_]datatype.Field{ map_type.key_field, map_type.item_field };
403	        const expected_entries = DataType{ .struct_ = .{ .fields = entries_fields[0..] } };
404	        if (!entries_data.data_type.eql(expected_entries)) return error.InvalidChildren;
405	    }
