407	    fn validateDictionaryIndexSigned(
408	        self: Self,
409	        comptime T: type,
410	        indices: []const T,
411	        start: usize,
412	        end: usize,
413	        dictionary_len: usize,
414	    ) ValidationError!void {
415	        if (indices.len < end) return error.BufferTooSmall;
416	        var pos = start;
417	        while (pos < end) : (pos += 1) {
418	            if (self.isNull(pos - start)) continue;
419	            const value = indices[pos];
420	            if (value < 0) return error.InvalidOffsets;
421	            const index = std.math.cast(usize, value) orelse return error.InvalidOffsets;
422	            if (index >= dictionary_len) return error.InvalidOffsets;
423	        }
424	    }
