426	    fn validateDictionaryIndexUnsigned(
427	        self: Self,
428	        comptime T: type,
429	        indices: []const T,
430	        start: usize,
431	        end: usize,
432	        dictionary_len: usize,
433	    ) ValidationError!void {
434	        if (indices.len < end) return error.BufferTooSmall;
435	        var pos = start;
436	        while (pos < end) : (pos += 1) {
437	            if (self.isNull(pos - start)) continue;
438	            const index = std.math.cast(usize, indices[pos]) orelse return error.InvalidOffsets;
439	            if (index >= dictionary_len) return error.InvalidOffsets;
440	        }
441	    }
