443	    fn validateDictionaryIndices(self: Self, dict: datatype.DictionaryType, start: usize, end: usize) ValidationError!void {
444	        if (self.buffers.len < 2) return error.InvalidBufferCount;
445	        const dictionary_ref = self.dictionary orelse return error.MissingDictionary;
446	        const dictionary_len = dictionary_ref.data().length;
447	
448	        return switch (dict.index_type.bit_width) {
449	            8 => if (dict.index_type.signed)
450	                self.validateDictionaryIndexSigned(i8, self.buffers[1].typedSlice(i8) catch return error.InvalidOffsetBuffer, start, end, dictionary_len)
451	            else
452	                self.validateDictionaryIndexUnsigned(u8, self.buffers[1].typedSlice(u8) catch return error.InvalidOffsetBuffer, start, end, dictionary_len),
453	            16 => if (dict.index_type.signed)
454	                self.validateDictionaryIndexSigned(i16, self.buffers[1].typedSlice(i16) catch return error.InvalidOffsetBuffer, start, end, dictionary_len)
455	            else
456	                self.validateDictionaryIndexUnsigned(u16, self.buffers[1].typedSlice(u16) catch return error.InvalidOffsetBuffer, start, end, dictionary_len),
457	            32 => if (dict.index_type.signed)
458	                self.validateDictionaryIndexSigned(i32, self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer, start, end, dictionary_len)
459	            else
460	                self.validateDictionaryIndexUnsigned(u32, self.buffers[1].typedSlice(u32) catch return error.InvalidOffsetBuffer, start, end, dictionary_len),
461	            64 => if (dict.index_type.signed)
462	                self.validateDictionaryIndexSigned(i64, self.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer, start, end, dictionary_len)
463	            else
464	                self.validateDictionaryIndexUnsigned(u64, self.buffers[1].typedSlice(u64) catch return error.InvalidOffsetBuffer, start, end, dictionary_len),
465	            else => error.InvalidOffsetBuffer,
466	        };
467	    }
