469	    // LargeListView offsets/sizes use 64-bit indices.
470	    fn validateOffsetsSizesI64(offsets: []const i64, sizes: []const i64, total_len: usize, child_len: usize) ValidationError!void {
471	        if (offsets.len < total_len) return error.BufferTooSmall;
472	        if (sizes.len < total_len) return error.BufferTooSmall;
473	        var i: usize = 0;
474	        while (i < total_len) : (i += 1) {
475	            const off = offsets[i];
476	            const size = sizes[i];
477	            if (off < 0 or size < 0) return error.InvalidOffsets;
478	            const off_usize = std.math.cast(usize, off) orelse return error.InvalidOffsets;
479	            const size_usize = std.math.cast(usize, size) orelse return error.InvalidOffsets;
480	            const end = std.math.add(usize, off_usize, size_usize) catch return error.InvalidOffsets;
481	            if (end > child_len) return error.InvalidOffsets;
482	        }
483	    }
484	
485	    pub fn validateLayout(self: Self) ValidationError!void {
486	        const dt = layoutDataType(self.data_type);
487	
488	        if (self.null_count) |count| {
489	            // null_count can never exceed the number of logical elements.
490	            if (count > self.length) return error.InvalidNullCount;
491	            // Null arrays have no validity bitmap; all elements are implicitly null.
492	            if (dt == .null) {
493	                if (count != self.length) return error.InvalidNullCount;
494	            } else if (!hasTopLevelValidityBitmap(dt)) {
495	                // Union arrays have no validity bitmap; null_count must be 0.
496	                if (count != 0) return error.InvalidNullCount;
497	            } else if (count != 0 and (self.buffers.len == 0 or self.buffers[0].isEmpty())) {
498	                return error.InvalidNullCount;
499	            }
500	        }
501	
502	        const total_len = std.math.add(usize, self.offset, self.length) catch return error.InvalidOffsets;
503	        const has_top_level_validity = hasTopLevelValidityBitmap(dt);
504	        if (has_top_level_validity and self.buffers.len > 0 and !self.buffers[0].isEmpty()) {
505	            const needed = try checkedBitmapByteLength(total_len);
506	            if (self.buffers[0].len() < needed) return error.BufferTooSmall;
507	        }
508	
509	        switch (dt) {
510	            .null => {},
511	            .string_view, .binary_view => {
512	                if (self.buffers.len < 2) return error.InvalidBufferCount;
513	                const variadic = if (self.buffers.len > 2) self.buffers[2..] else &[_]SharedBuffer{};
514	                try validateByteViews(self.buffers[1].data, total_len, variadic);
515	            },
516	            .bool => {
517	                if (self.buffers.len < 2) return error.InvalidBufferCount;
518	                const needed = try checkedBitmapByteLength(total_len);
519	                if (self.buffers[1].len() < needed) return error.BufferTooSmall;
520	            },
521	            .list_view, .large_list_view => {
522	                if (self.buffers.len < 3) return error.InvalidBufferCount;
523	                if (self.children.len != 1) return error.InvalidChildren;
524	
525	                const offset_width = offsetByteWidth(dt).?;
526	                if (self.buffers[1].len() % offset_width != 0) return error.InvalidOffsetBuffer;
527	                if (self.buffers[2].len() % offset_width != 0) return error.InvalidOffsetBuffer;
528	
529	                // Views are validated against the child logical length.
530	                const child_data = self.children[0].data();
531	                const child_len = std.math.add(usize, child_data.length, child_data.offset) catch return error.InvalidChildren;
532	                if (offset_width == 4) {
533	                    const offsets = self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer;
534	                    const sizes = self.buffers[2].typedSlice(i32) catch return error.InvalidOffsetBuffer;
535	                    try validateOffsetsSizesI32(offsets, sizes, total_len, child_len);
536	                } else {
537	                    const offsets = self.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer;
538	                    const sizes = self.buffers[2].typedSlice(i64) catch return error.InvalidOffsetBuffer;
539	                    try validateOffsetsSizesI64(offsets, sizes, total_len, child_len);
540	                }
541	            },
542	            .string, .binary, .list, .map, .large_string, .large_binary, .large_list => {
543	                if (self.buffers.len < 2) return error.InvalidBufferCount;
544	                const offset_width = offsetByteWidth(dt).?;
545	                if (self.buffers[1].len() % offset_width != 0) return error.InvalidOffsetBuffer;
546	
547	                const is_list = dt == .list or dt == .large_list or dt == .map;
548	                if (is_list) {
549	                    if (self.children.len != 1) return error.InvalidChildren;
550	                } else if (self.buffers.len < 3) {
551	                    return error.InvalidBufferCount;
552	                }
553	
554	                const data_len = if (is_list) blk: {
555	                    const child_data = self.children[0].data();
556	                    break :blk std.math.add(usize, child_data.length, child_data.offset) catch return error.InvalidChildren;
557	                } else if (self.buffers.len >= 3) self.buffers[2].len() else 0;
558	
559	                if (offset_width == 4) {
560	                    const offsets = self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer;
561	                    try validateOffsetsI32(offsets, total_len, data_len);
562	                } else {
563	                    const offsets = self.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer;
564	                    try validateOffsetsI64(offsets, total_len, data_len);
565	                }
566	            },
567	            .fixed_size_list, .struct_ => {
568	                if (self.buffers.len < 1) return error.InvalidBufferCount;
569	                const expected = switch (dt) {
570	                    .fixed_size_list => 1,
571	                    .struct_ => |st| st.fields.len,
572	                    else => 0,
573	                };
574	                if (self.children.len != expected) return error.InvalidChildren;
575	                if (dt == .fixed_size_list) {
576	                    const list_size = std.math.cast(usize, dt.fixed_size_list.list_size) orelse return error.InvalidChildren;
577	                    const required = std.math.mul(usize, total_len, list_size) catch return error.InvalidChildren;
578	                    const child_data = self.children[0].data();
579	                    const child_total = std.math.add(usize, child_data.length, child_data.offset) catch return error.InvalidChildren;
580	                    if (child_total < required) return error.InvalidChildren;
581	                }
582	            },
583	            .dictionary => |dict| {
584	                if (self.buffers.len < 2) return error.InvalidBufferCount;
585	                const byte_width = dict.index_type.bit_width / 8;
586	                if (byte_width == 0) return error.InvalidOffsetBuffer;
587	                const needed = std.math.mul(usize, total_len, byte_width) catch return error.BufferTooSmall;
588	                if (self.buffers[1].len() < needed) return error.BufferTooSmall;
589	                if (self.dictionary == null) return error.MissingDictionary;
590	            },
591	            .sparse_union => |uni| {
592	                if (self.buffers.len < 1) return error.InvalidBufferCount;
593	                if (self.children.len != uni.fields.len) return error.InvalidChildren;
594	                if (self.buffers[0].len() < total_len) return error.BufferTooSmall;
595	                const type_ids = self.buffers[0].typedSlice(i8) catch return error.InvalidOffsetBuffer;
596	                try validateUnionTypeIds(uni, type_ids, self.offset, total_len);
597	            },
598	            .dense_union => |uni| {
599	                if (self.buffers.len < 2) return error.InvalidBufferCount;
600	                if (self.children.len != uni.fields.len) return error.InvalidChildren;
601	                if (self.buffers[0].len() < total_len) return error.BufferTooSmall;
602	                const needed = std.math.mul(usize, total_len, @sizeOf(i32)) catch return error.BufferTooSmall;
603	                if (self.buffers[1].len() < needed) return error.BufferTooSmall;
604	                const type_ids = self.buffers[0].typedSlice(i8) catch return error.InvalidOffsetBuffer;
605	                const offsets = self.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer;
606	                try validateUnionTypeIds(uni, type_ids, self.offset, total_len);
607	                try validateDenseUnionOffsets(uni, type_ids, offsets, self.children, self.offset, total_len);
608	            },
609	            .run_end_encoded => {
610	                if (self.buffers.len != 0) return error.InvalidBufferCount;
611	                if (self.children.len != 2) return error.InvalidChildren;
612	
613	                const run_ends = self.children[0].data();
614	                const values = self.children[1].data();
615	                const run_end_dt = switch (dt.run_end_encoded.run_end_type.bit_width) {
616	                    16 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int16 = {} } else return error.InvalidOffsetBuffer,
617	                    32 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int32 = {} } else return error.InvalidOffsetBuffer,
618	                    64 => if (dt.run_end_encoded.run_end_type.signed) DataType{ .int64 = {} } else return error.InvalidOffsetBuffer,
619	                    else => return error.InvalidOffsetBuffer,
620	                };
621	                if (!std.meta.eql(run_ends.data_type, run_end_dt)) return error.InvalidChildren;
622	                if (run_ends.buffers.len < 2) return error.InvalidChildren;
623	
624	                const byte_width = switch (dt) {
625	                    .run_end_encoded => |ree| ree.run_end_type.bit_width / 8,
626	                    else => 0,
627	                };
628	                if (byte_width == 0) return error.InvalidOffsetBuffer;
629	                if (run_ends.buffers[1].len() % byte_width != 0) return error.InvalidOffsetBuffer;
630	
631	                // One run end per value in the values child.
632	                const run_count = run_ends.length;
633	                if (values.length != run_count) return error.InvalidChildren;
634	
635	                const run_ends_slice_start = run_ends.offset;
636	                const run_ends_slice_end = std.math.add(usize, run_ends.offset, run_ends.length) catch return error.InvalidOffsets;
637	
638	                switch (byte_width) {
639	                    2 => if (dt.run_end_encoded.run_end_type.signed)
640	                        try validateRunEndsSigned(i16, (run_ends.buffers[1].typedSlice(i16) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len)
641	                    else
642	                        try validateRunEndsUnsigned(u16, (run_ends.buffers[1].typedSlice(u16) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len),
643	                    4 => if (dt.run_end_encoded.run_end_type.signed)
644	                        try validateRunEndsSigned(i32, (run_ends.buffers[1].typedSlice(i32) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len)
645	                    else
646	                        try validateRunEndsUnsigned(u32, (run_ends.buffers[1].typedSlice(u32) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len),
647	                    8 => if (dt.run_end_encoded.run_end_type.signed)
648	                        try validateRunEndsSigned(i64, (run_ends.buffers[1].typedSlice(i64) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len)
649	                    else
650	                        try validateRunEndsUnsigned(u64, (run_ends.buffers[1].typedSlice(u64) catch return error.InvalidOffsetBuffer)[run_ends_slice_start..run_ends_slice_end], total_len),
651	                    else => return error.InvalidOffsetBuffer,
652	                }
653	            },
654	            else => {
655	                if (fixedWidthByteSize(dt)) |byte_width| {
656	                    if (self.buffers.len < 2) return error.InvalidBufferCount;
657	                    if (byte_width == 0) return error.InvalidOffsetBuffer;
658	                    const needed = std.math.mul(usize, total_len, byte_width) catch return error.BufferTooSmall;
659	                    if (self.buffers[1].len() < needed) return error.BufferTooSmall;
660	                }
661	            },
662	        }
663	    }
664	
665	    pub fn validateFull(self: Self) ValidationError!void {
666	        try self.validateLayout();
667	        const dt = layoutDataType(self.data_type);
668	        const total_len = std.math.add(usize, self.offset, self.length) catch return error.InvalidOffsets;
669	
670	        if (self.null_count) |expected_count| {
671	            if (hasTopLevelValidityBitmap(dt) and self.buffers.len > 0 and !self.buffers[0].isEmpty()) {
672	                const validity_bitmap = ValidityBitmap.fromBuffer(self.buffers[0], total_len);
673	                var actual_count: usize = 0;
674	                var i: usize = 0;
675	                while (i < self.length) : (i += 1) {
676	                    if (!(validity_bitmap.isValid(self.offset + i) catch unreachable)) actual_count += 1;
677	                }
678	                if (actual_count != expected_count) return error.InvalidNullCount;
679	            }
680	        }
681	
682	        switch (dt) {
683	            .struct_ => |st| try self.validateStructChildren(st.fields, total_len),
684	            .map => |map_type| try self.validateMapChild(map_type),
685	            .dictionary => |dict| try self.validateDictionaryIndices(dict, self.offset, total_len),
686	            else => {},
687	        }
688	
689	        for (self.children) |child| try child.data().validateFull();
690	        if (self.dictionary) |dict| try dict.data().validateFull();
691	    }
692	};
