13	    allocator: std.mem.Allocator,
14	    // Shared reference count for ArrayRef clones.
15	    ref_count: std.atomic.Value(u32),
16	    // Owned array payload (buffers/children/dictionary containers).
17	    data: ArrayData,
18	    // Optional owner hook used by FFI imports to keep foreign memory alive.
19	    owner_ctx: ?*anyopaque = null,
20	    owner_retain: ?*const fn (?*anyopaque) void = null,
21	    owner_release: ?*const fn (?*anyopaque) void = null,
