24	pub const ArrayRef = struct {
25	    // Pointer to shared array node.
26	    node: *ArrayNode,
27	
28	    /// Increment reference count and return another handle to the same array.
29	    pub fn retain(self: ArrayRef) ArrayRef {
30	        _ = self.node.ref_count.fetchAdd(1, .monotonic);
31	        return self;
32	    }
33	
34	    /// Release one handle; destroy node when last reference is dropped.
35	    pub fn release(self: *ArrayRef) void {
36	        if (self.node.ref_count.fetchSub(1, .acq_rel) != 1) return;
37	        const allocator = self.node.allocator;
38	
39	        for (self.node.data.buffers) |buf| {
40	            var owned = buf;
41	            owned.release();
42	        }
43	        allocator.free(self.node.data.buffers);
44	
45	        for (self.node.data.children) |child| {
46	            var owned = child;
47	            owned.release();
48	        }
49	        allocator.free(self.node.data.children);
50	
51	        if (self.node.data.dictionary) |dict| {
52	            var owned = dict;
53	            owned.release();
54	        }
55	
56	        if (self.node.owner_release) |owner_release| {
57	            owner_release(self.node.owner_ctx);
58	        }
59	        allocator.destroy(self.node);
60	    }
61	
62	    /// Borrow immutable access to the underlying array layout.
63	    pub fn data(self: ArrayRef) *const ArrayData {
64	        return &self.node.data;
65	    }
66	
67	    /// Create a sliced ArrayRef while preserving ownership correctness.
68	    ///
69	    /// The slice semantics are type-aware:
70	    /// - list/map keep child in parent coordinate space (offset-driven view)
71	    /// - struct slices children to keep element alignment
72	    /// - dictionary keeps child/dictionary shared
73	    pub fn slice(self: ArrayRef, offset: usize, length: usize) !ArrayRef {
74	        var sliced = self.node.data.slice(offset, length);
75	        const allocator = self.node.allocator;
76	
77	        const buffers = try allocator.alloc(SharedBuffer, sliced.buffers.len);
78	        errdefer {
79	            for (buffers) |buf| {
80	                var owned = buf;
81	                owned.release();
82	            }
83	            allocator.free(buffers);
84	        }
85	        for (sliced.buffers, 0..) |buf, i| {
86	            buffers[i] = buf.retain();
87	        }
88	
89	        const children = try allocator.alloc(ArrayRef, sliced.children.len);
90	        var child_count: usize = 0;
91	        errdefer {
92	            var i: usize = 0;
93	            while (i < child_count) : (i += 1) {
94	                children[i].release();
95	            }
96	            allocator.free(children);
97	        }
98	
99	        var dict_ref: ?ArrayRef = null;
100	        if (sliced.dictionary) |dict| dict_ref = dict.retain();
101	        errdefer if (dict_ref) |*owned| owned.release();
102	
103	        switch (sliced.data_type) {
104	            .struct_ => {
105	                // Struct requires child-wise slicing to keep row alignment.
106	                const total_offset = self.node.data.offset + offset;
107	                var i: usize = 0;
108	                while (i < sliced.children.len) : (i += 1) {
109	                    children[i] = try sliced.children[i].slice(total_offset, length);
110	                    child_count += 1;
111	                }
112	            },
113	            .list, .large_list, .map, .list_view, .large_list_view, .fixed_size_list, .sparse_union, .dense_union, .run_end_encoded, .dictionary => {
114	                // Explicit shallow-slice families:
115	                // - list/list_view/map/fixed_size_list keep child coordinate space shared
116	                // - union/REE keep shared child/run-end coordinate spaces
117	                // - dictionary keeps child/dictionary shared
118	                var i: usize = 0;
119	                while (i < sliced.children.len) : (i += 1) {
120	                    children[i] = sliced.children[i].retain();
121	                    child_count += 1;
122	                }
123	            },
124	            else => {
125	                // Default shallow slice for primitive and most nested representations.
126	                var i: usize = 0;
127	                while (i < sliced.children.len) : (i += 1) {
128	                    children[i] = sliced.children[i].retain();
129	                    child_count += 1;
130	                }
131	            },
132	        }
133	
134	        sliced.buffers = buffers;
135	        sliced.children = children;
136	        sliced.dictionary = dict_ref;
137	
138	        return ArrayRef.fromOwnedWithOwner(
139	            allocator,
140	            sliced,
141	            self.node.owner_ctx,
142	            self.node.owner_retain,
143	            self.node.owner_release,
144	        );
145	    }
