147	    /// Create an ArrayRef by wrapping an owned ArrayData layout.
148	    ///
149	    /// This is a minimal wrapper. Callers must ensure the layout is safe to
150	    /// release with the provided allocator.
151	    pub fn fromOwnedUnsafe(allocator: std.mem.Allocator, layout: ArrayData) !ArrayRef {
152	        const node = try allocator.create(ArrayNode);
153	        node.* = .{
154	            .allocator = allocator,
155	            .ref_count = std.atomic.Value(u32).init(1),
156	            .data = layout,
157	        };
158	        return .{ .node = node };
159	    }
