161	    /// Create an ArrayRef by wrapping an owned ArrayData layout with owner hooks.
162	    pub fn fromOwnedWithOwner(
163	        allocator: std.mem.Allocator,
164	        layout: ArrayData,
165	        owner_ctx: ?*anyopaque,
166	        owner_retain: ?*const fn (?*anyopaque) void,
167	        owner_release: ?*const fn (?*anyopaque) void,
168	    ) !ArrayRef {
169	        if (owner_retain) |retain_fn| retain_fn(owner_ctx);
170	        errdefer if (owner_release) |release_fn| release_fn(owner_ctx);
171	
172	        const node = try allocator.create(ArrayNode);
173	        node.* = .{
174	            .allocator = allocator,
175	            .ref_count = std.atomic.Value(u32).init(1),
176	            .data = layout,
177	            .owner_ctx = owner_ctx,
178	            .owner_retain = owner_retain,
179	            .owner_release = owner_release,
180	        };
181	        return .{ .node = node };
182	    }
