206	            var i: usize = 0;
207	            while (i < buf_count) : (i += 1) {
208	                var owned = buffers[i];
209	                owned.release();
210	            }
211	            allocator.free(buffers);
212	        }
213	        for (layout.buffers, 0..) |buf, i| {
214	            buffers[i] = buf.retain();
215	            buf_count += 1;
216	        }
217	
218	        const children = try allocator.alloc(ArrayRef, layout.children.len);
219	        var child_count: usize = 0;
220	        errdefer {
221	            var i: usize = 0;
222	            while (i < child_count) : (i += 1) {
