30	pub const RecordBatch = struct {
31	    allocator: std.mem.Allocator,
32	    schema_ref: SchemaRef,
33	    columns: []ArrayRef,
34	    num_rows: usize,
35	
36	    const Self = @This();
37	
38	    /// Initialize and return a new instance. Takes ownership of `schema_ref`
39	    /// (caller must retain before passing if the ref is still needed elsewhere).
40	    pub fn init(allocator: std.mem.Allocator, schema_ref: SchemaRef, columns: []const ArrayRef) !Self {
41	        const sc = schema_ref.schema();
42	        if (sc.fields.len != columns.len) return RecordBatchError.InvalidColumnCount;
43	
44	        const num_rows = if (columns.len == 0) 0 else columns[0].data().length;
45	        for (columns, 0..) |col_ref, i| {
46	            const data = col_ref.data();
47	            try data.validateLayout();
48	            if (data.length != num_rows) return RecordBatchError.InvalidColumnLength;
49	            if (!data.data_type.eql(sc.fields[i].data_type.*)) return RecordBatchError.InvalidColumnType;
50	            if (!sc.fields[i].nullable and data.hasNulls()) return RecordBatchError.NullInNonNullableField;
51	        }
52	
53	        const owned_columns = try allocator.alloc(ArrayRef, columns.len);
54	        errdefer allocator.free(owned_columns);
55	        for (columns, 0..) |col_ref, i| {
56	            owned_columns[i] = col_ref.retain();
57	        }
58	
59	        return .{
60	            .allocator = allocator,
61	            .schema_ref = schema_ref,
62	            .columns = owned_columns,
63	            .num_rows = num_rows,
64	        };
65	    }
66	
67	    /// Convenience: wrap a borrowed Schema into a SchemaRef and call init.
68	    pub fn initBorrowed(allocator: std.mem.Allocator, borrowed_schema: Schema, columns: []const ArrayRef) !Self {
69	        var ref = try SchemaRef.fromBorrowed(allocator, borrowed_schema);
70	        errdefer ref.release();
71	        return init(allocator, ref, columns);
72	    }
73	
74	    /// Release resources owned by this instance.
75	    pub fn deinit(self: *Self) void {
76	        for (self.columns) |col_ref| {
77	            var owned = col_ref;
78	            owned.release();
79	        }
80	        self.allocator.free(self.columns);
81	        self.schema_ref.release();
82	    }
