88	    pub fn numColumns(self: Self) usize {
89	        return self.columns.len;
90	    }
91	
92	    pub fn column(self: *const Self, index: usize) *const ArrayRef {
93	        std.debug.assert(index < self.columns.len);
94	        return &self.columns[index];
95	    }
