98	        return self.schema_ref.schema();
99	    }
100	
101	    pub fn columnByName(self: *const Self, name: []const u8) ?*const ArrayRef {
102	        const index = self.schema_ref.fieldIndex(name) orelse return null;
103	        if (index >= self.columns.len) return null;
104	        return &self.columns[index];
105	    }
106	
107	    /// Create a logical slice view over the current value.
108	    pub fn slice(self: *const Self, offset: usize, length: usize) !Self {
109	        const end = std.math.add(usize, offset, length) catch return RecordBatchError.SliceOutOfBounds;
110	        if (offset > self.num_rows or end > self.num_rows) return RecordBatchError.SliceOutOfBounds;
111	
112	        const sliced_columns = try self.allocator.alloc(ArrayRef, self.columns.len);
113	        var count: usize = 0;
114	        errdefer {
115	            var i: usize = 0;
116	            while (i < count) : (i += 1) {
117	                sliced_columns[i].release();
118	            }
119	            self.allocator.free(sliced_columns);
120	        }
121	
122	        for (self.columns, 0..) |column_ref, i| {
123	            sliced_columns[i] = try column_ref.slice(offset, length);
124	            count += 1;
125	        }
126	
127	        return .{
128	            .allocator = self.allocator,
129	            .schema_ref = self.schema_ref.retain(),
130	            .columns = sliced_columns,
131	            .num_rows = length,
132	        };
133	    }
134	};
