140	    finished: bool = false,
141	
142	    const Self = @This();
143	
144	    /// Initialize and return a new instance. Takes ownership of `schema_ref`.
145	    pub fn init(allocator: std.mem.Allocator, schema_ref: SchemaRef) !Self {
146	        const slots = try allocator.alloc(?ArrayRef, schema_ref.schema().fields.len);
147	        @memset(slots, null);
148	        return .{
149	            .allocator = allocator,
150	            .schema_ref = schema_ref,
151	            .columns = slots,
152	        };
153	    }
154	
155	    /// Convenience: wrap a borrowed Schema into a SchemaRef and call init.
156	    pub fn initBorrowed(allocator: std.mem.Allocator, borrowed_schema: Schema) !Self {
157	        var ref = try SchemaRef.fromBorrowed(allocator, borrowed_schema);
158	        errdefer ref.release();
159	        return init(allocator, ref);
160	    }
161	
162	    /// Release resources owned by this instance.
163	    pub fn deinit(self: *Self) void {
164	        self.releaseColumns();
165	        self.allocator.free(self.columns);
166	        self.schema_ref.release();
167	    }
168	
169	    fn releaseColumns(self: *Self) void {
170	        for (self.columns, 0..) |slot, i| {
171	            if (slot) |col_ref| {
172	                var owned = col_ref;
173	                owned.release();
174	                self.columns[i] = null;
175	            }
176	        }
177	    }
178	
179	    pub fn setColumn(self: *Self, index: usize, column_ref: ArrayRef) RecordBatchBuilderError!void {
180	        if (self.finished) return RecordBatchBuilderError.AlreadyFinished;
181	        if (index >= self.columns.len) return RecordBatchBuilderError.InvalidColumnIndex;
182	        if (self.columns[index] != null) return RecordBatchBuilderError.ColumnAlreadySet;
183	        self.columns[index] = column_ref.retain();
184	    }
185	
186	    pub fn setColumnByName(self: *Self, name: []const u8, column_ref: ArrayRef) RecordBatchBuilderError!void {
187	        if (self.finished) return RecordBatchBuilderError.AlreadyFinished;
188	        for (self.schema_ref.schema().fields, 0..) |field, i| {
189	            if (std.mem.eql(u8, field.name, name)) return self.setColumn(i, column_ref);
190	        }
191	        return RecordBatchBuilderError.UnknownField;
192	    }
193	
194	    /// Finalize builder state and return an immutable array reference.
195	    pub fn finish(self: *Self) !RecordBatch {
196	        if (self.finished) return RecordBatchBuilderError.AlreadyFinished;
197	
198	        const refs = try self.allocator.alloc(ArrayRef, self.columns.len);
199	        defer self.allocator.free(refs);
200	
201	        for (self.columns, 0..) |slot, i| {
202	            const col_ref = slot orelse return RecordBatchBuilderError.MissingColumn;
203	            refs[i] = col_ref;
204	        }
205	
206	        const batch = try RecordBatch.init(self.allocator, self.schema_ref.retain(), refs);
207	        // The resulting batch now owns retained column refs, so the builder
208	        // should not keep additional holds after a successful finish.
209	        self.releaseColumns();
210	        self.finished = true;
211	        return batch;
212	    }
213	
214	    /// Reset state while retaining reusable capacity when possible.
215	    pub fn reset(self: *Self) RecordBatchBuilderError!void {
216	        // Reset keeps capacity and can be called in any state.
217	        self.releaseColumns();
218	        self.finished = false;
219	    }
220	
221	    /// Clear state and release reusable buffers when required.
222	    pub fn clear(self: *Self) RecordBatchBuilderError!void {
223	        // Clear is a hard cleanup operation and is allowed even before finish.
224	        self.releaseColumns();
225	        self.finished = false;
226	    }
