29	/// Ensure validity storage exists, mark the new appended slot as null, and bump null count.
30	pub fn ensureValidityForNull(
31	    allocator: std.mem.Allocator,
32	    validity: *?OwnedBuffer,
33	    null_count: *usize,
34	    new_len: usize,
35	) !void {
36	    std.debug.assert(new_len > 0);
37	    if (validity.* == null) {
38	        var buf = try initValidityAllValid(allocator, new_len);
39	        bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
40	        validity.* = buf;
41	        null_count.* += 1;
42	        return;
43	    }
44	    var buf = &validity.*.?;
45	    try ensureBitmapCapacity(buf, new_len);
46	    bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
47	    null_count.* += 1;
48	}
