51	pub fn setValidBit(validity: *?OwnedBuffer, index: usize) !void {
52	    if (validity.* == null) return;
53	    var buf = &validity.*.?;
54	    try ensureBitmapCapacity(buf, index + 1);
55	    bitmap.setBit(buf.data[0..bitmap.byteLength(index + 1)], index);
