86	    /// Clear state and release reusable buffers when required.
87	    pub fn clear(self: *Self) BuilderError!void {
88	        if (self.state != .finished) return BuilderError.NotFinished;
89	        self.values.deinit();
90	        if (self.validity) |*valid| valid.deinit();
91	        self.validity = null;
92	        self.len = 0;
93	        self.null_count = 0;
94	        self.state = .ready;
95	    }
