97	    fn ensureValuesCapacity(self: *Self, new_len: usize) !void {
98	        const needed = bitmap.byteLength(new_len);
99	        if (needed <= self.values.len()) return;
100	        try self.values.resize(needed);
101	    }
102	
103	    fn ensureValidityForNull(self: *Self, new_len: usize) !void {
104	        if (self.validity == null) {
105	            var buf = try initValidityAllValid(self.allocator, new_len);
106	            bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
107	            self.validity = buf;
108	            self.null_count += 1;
109	            return;
110	        }
111	        var buf = &self.validity.?;
112	        try ensureBitmapCapacity(buf, new_len);
113	        bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
114	        self.null_count += 1;
115	    }
116	
117	    fn setValidBit(self: *Self, index: usize) !void {
118	        if (self.validity == null) return;
119	        var buf = &self.validity.?;
120	        try ensureBitmapCapacity(buf, index + 1);
121	        bitmap.setBit(buf.data[0..bitmap.byteLength(index + 1)], index);
122	    }
