76	            return .{
77	                .allocator = allocator,
78	                .values = try OwnedBuffer.init(allocator, capacity * @sizeOf(T)),
79	            };
80	        }
81	
82	        /// Release resources owned by this instance.
83	        pub fn deinit(self: *Self) void {
84	            self.values.deinit();
85	            if (self.validity) |*valid| valid.deinit();
86	        }
