89	        pub fn reset(self: *Self) Error!void {
90	            if (self.state != .finished) return Error.NotFinished;
91	            self.len = 0;
92	            self.null_count = 0;
93	            self.state = .ready;
94	        }
95	
96	        /// Clear state and release reusable buffers when required.
97	        pub fn clear(self: *Self) Error!void {
98	            if (self.state != .finished) return Error.NotFinished;
