9	pub fn initValidityAllValid(allocator: std.mem.Allocator, bit_len: usize) !OwnedBuffer {
10	    const used_bytes = bitmap.byteLength(bit_len);
11	    var buf = try OwnedBuffer.init(allocator, used_bytes);
12	    if (used_bytes > 0) {
13	        @memset(buf.data[0..used_bytes], 0xFF);
14	        const remainder = bit_len & 7;
15	        if (remainder != 0) {
16	            const keep_mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
17	            buf.data[used_bytes - 1] &= keep_mask;
18	        }
19	    }
20	    return buf;
21	}
22	
23	pub fn ensureBitmapCapacity(buf: *OwnedBuffer, bit_len: usize) !void {
24	    const needed = bitmap.byteLength(bit_len);
25	    if (needed <= buf.len()) return;
26	    try buf.resize(needed);
27	}
