106	            bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
107	            self.validity = buf;
108	            self.null_count += 1;
109	            return;
110	        }
111	        var buf = &self.validity.?;
112	        try ensureBitmapCapacity(buf, new_len);
113	        bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
114	        self.null_count += 1;
115	    }
