117	    fn setValidBit(self: *Self, index: usize) !void {
118	        if (self.validity == null) return;
119	        var buf = &self.validity.?;
120	        try ensureBitmapCapacity(buf, index + 1);
121	        bitmap.setBit(buf.data[0..bitmap.byteLength(index + 1)], index);
122	    }
