124	    /// Append one logical value into the builder.
125	    pub fn append(self: *Self, value: bool) !void {
126	        if (self.state == .finished) return BuilderError.AlreadyFinished;
127	        const next_len = self.len + 1;
128	        try self.ensureValuesCapacity(next_len);
129	        bitmap.writeBit(self.values.data[0..bitmap.byteLength(next_len)], self.len, value);
130	        try self.setValidBit(self.len);
131	        self.len = next_len;
132	    }
