134	    /// Append a null entry into the builder.
135	    pub fn appendNull(self: *Self) !void {
136	        if (self.state == .finished) return BuilderError.AlreadyFinished;
137	        const next_len = self.len + 1;
138	        try self.ensureValuesCapacity(next_len);
139	        try self.ensureValidityForNull(next_len);
140	        self.len = next_len;
141	    }
