143	    /// Finalize builder state and return an immutable array reference.
144	    pub fn finish(self: *Self) !ArrayRef {
145	        if (self.state == .finished) return BuilderError.AlreadyFinished;
146	        const validity_buf = if (self.validity) |*buf| try buf.toShared(bitmap.byteLength(self.len)) else SharedBuffer.empty;
147	        self.buffers[0] = validity_buf;
148	        self.buffers[1] = try self.values.toShared(bitmap.byteLength(self.len));
149	
150	        const buffers = try self.allocator.alloc(SharedBuffer, 2);
151	        buffers[0] = self.buffers[0];
152	        buffers[1] = self.buffers[1];
153	
154	        const data = ArrayData{
155	            .data_type = BOOL_TYPE,
156	            .length = self.len,
157	            .null_count = self.null_count,
158	            .buffers = buffers,
159	        };
