20	/// Generic array view for fixed-width primitive types.
21	pub fn PrimitiveArray(comptime T: type) type {
22	    return struct {
23	        data: *const ArrayData,
24	
25	        const Self = @This();
26	
27	        pub const Error = AccessorError;
28	
29	        /// Return the logical length.
30	        pub fn len(self: Self) usize {
31	            return self.data.length;
32	        }
33	
34	        /// Check whether the element at index is null.
35	        pub fn isNull(self: Self, i: usize) bool {
36	            return self.data.isNull(i);
37	        }
38	
39	        pub fn values(self: Self) Error![]const T {
40	            // Primitive arrays require [validity] and [values] buffers.
41	            const raw = try self.data.typedBufferAt(1, T);
42	            const start = self.data.offset;
43	            const end = try self.data.logicalEnd();
44	            if (end > raw.len) return error.BufferTooSmall;
45	            return raw[start..end];
46	        }
47	
48	        /// Return the logical value view at the requested index.
49	        pub fn value(self: Self, i: usize) Error!T {
50	            if (i >= self.data.length) return error.IndexOutOfBounds;
51	            return (try self.values())[i];
52	        }
53	    };
54	}
