56	/// Generic builder for fixed-width primitive arrays.
57	/// The caller must specify the data type and handle validity bits as needed.
58	pub fn PrimitiveBuilder(comptime T: type, comptime dtype: DataType) type {
59	    return struct {
60	        allocator: std.mem.Allocator,
61	        values: OwnedBuffer,
62	        validity: ?OwnedBuffer = null,
63	        buffers: [2]SharedBuffer = undefined,
64	        len: usize = 0,
65	        null_count: usize = 0,
66	        state: BuilderState = .ready,
67	
68	        const Self = @This();
69	
70	        const Error = error{ AlreadyFinished, NotFinished };
71	
72	        const TYPE: DataType = dtype;
73	
74	        /// Initialize and return a new instance.
75	        pub fn init(allocator: std.mem.Allocator, capacity: usize) !Self {
76	            return .{
77	                .allocator = allocator,
78	                .values = try OwnedBuffer.init(allocator, capacity * @sizeOf(T)),
79	            };
80	        }
81	
82	        /// Release resources owned by this instance.
83	        pub fn deinit(self: *Self) void {
84	            self.values.deinit();
85	            if (self.validity) |*valid| valid.deinit();
86	        }
87	
88	        /// Reset state while retaining reusable capacity when possible.
89	        pub fn reset(self: *Self) Error!void {
90	            if (self.state != .finished) return Error.NotFinished;
91	            self.len = 0;
92	            self.null_count = 0;
93	            self.state = .ready;
94	        }
95	
96	        /// Clear state and release reusable buffers when required.
97	        pub fn clear(self: *Self) Error!void {
98	            if (self.state != .finished) return Error.NotFinished;
99	            self.values.deinit();
100	            if (self.validity) |*valid| valid.deinit();
101	            self.validity = null;
102	            self.len = 0;
103	            self.null_count = 0;
104	            self.state = .ready;
105	        }
106	
107	        fn ensureValuesCapacity(self: *Self, new_len: usize) !void {
108	            const capacity = self.values.len() / @sizeOf(T);
109	            if (new_len <= capacity) return;
110	            try self.values.resize(new_len * @sizeOf(T));
111	        }
112	
113	        /// Append one logical value into the builder.
114	        pub fn append(self: *Self, value: T) !void {
115	            if (self.state == .finished) return Error.AlreadyFinished;
116	            const next_len = self.len + 1;
117	            try self.ensureValuesCapacity(next_len);
118	            const slice = std.mem.bytesAsSlice(T, self.values.data);
119	            slice[self.len] = value;
120	            try array_utils.setValidBit(&self.validity, self.len);
121	            self.len = next_len;
122	        }
123	
124	        /// Append a null entry into the builder.
125	        pub fn appendNull(self: *Self) !void {
126	            if (self.state == .finished) return Error.AlreadyFinished;
127	            const next_len = self.len + 1;
128	            try self.ensureValuesCapacity(next_len);
129	            try array_utils.ensureValidityForNull(self.allocator, &self.validity, &self.null_count, next_len);
130	            self.len = next_len;
131	        }
132	
133	        /// Finalize builder state and return an immutable array reference.
134	        pub fn finish(self: *Self) !ArrayRef {
135	            if (self.state == .finished) return Error.AlreadyFinished;
136	            const validity_buf = if (self.validity) |*buf| try buf.toShared(bitmap.byteLength(self.len)) else SharedBuffer.empty;
137	            self.buffers[0] = validity_buf;
138	            self.buffers[1] = try self.values.toShared(self.len * @sizeOf(T));
139	
140	            const buffers = try self.allocator.alloc(SharedBuffer, 2);
141	            buffers[0] = self.buffers[0];
142	            buffers[1] = self.buffers[1];
143	
144	            const data = ArrayData{
145	                .data_type = TYPE,
146	                .length = self.len,
147	                .null_count = self.null_count,
148	                .buffers = buffers,
149	            };
150	
151	            self.state = .finished;
152	            return ArrayRef.fromOwnedUnsafe(self.allocator, data);
153	        }
154	
155	        /// Finalize output and then reset builder state for reuse.
156	        pub fn finishReset(self: *Self) !ArrayRef {
157	            const finished_ref = try self.finish();
158	            try self.reset();
159	            return finished_ref;
160	        }
161	    };
162	}
