3	/// Default byte alignment for Arrow-compatible buffer allocations (64-byte SIMD-friendly).
4	pub const ALIGNMENT: usize = 64;
5	const ALIGNMENT_VALUE: std.mem.Alignment = std.mem.Alignment.fromByteUnits(ALIGNMENT);
6	
7	const empty_storage: [0]u8 align(ALIGNMENT) = .{};
8	
9	/// Round `size` up to the next `ALIGNMENT`-byte boundary.
10	/// Use this to determine the minimum capacity for a buffer storing `size` bytes.
11	///
12	/// Demo (`ALIGNMENT = 64`):
13	/// - `alignedSize(0) == (0 + 64 - 1) & ~(64 - 1) == 63 & ~63 == 0`
14	/// - `alignedSize(1) == (1 + 64 - 1) & ~(64 - 1) == 64 & ~63 == 64`
15	/// - `alignedSize(64) == (64 + 64 - 1) & ~(64 - 1) == 127 & ~63 == 64`
16	/// - `alignedSize(65) == (65 + 64 - 1) & ~(64 - 1) == 128 & ~63 == 128`
17	pub inline fn alignedSize(size: usize) usize {
18	    return (size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
19	}
