21	// Internal ref-counted storage backing shared buffers.
22	const BufferStorage = struct {
23	    // Allocator used to create and free this storage.
24	    allocator: std.mem.Allocator,
25	    // Aligned buffer bytes owned by this storage.
26	    data: []align(ALIGNMENT) u8,
27	    // Shared reference count for all SharedBuffer views.
28	    ref_count: std.atomic.Value(u32),
29	    // Custom release hook for external/FFI-managed memory.
30	    release_fn: *const fn (*BufferStorage) void,
31	
32	    // Default release: free the data and destroy the control block.
33	    fn releaseDefault(storage: *BufferStorage) void {
34	        storage.allocator.free(storage.data);
35	        storage.allocator.destroy(storage);
36	    }
37	};
