133	/// Mutable, uniquely owned buffer used by array builders.
134	///
135	/// Capacity is always a multiple of `ALIGNMENT` bytes and the backing memory
136	/// is zero-initialised on allocation and resize.  Call `toShared` to transfer
137	/// ownership to an immutable `SharedBuffer` — the `OwnedBuffer` is emptied in
138	/// the process and must not be written to afterwards.
139	pub const OwnedBuffer = struct {
140	    /// Aligned mutable backing storage.
141	    data: []align(ALIGNMENT) u8,
142	    /// Allocator used for all (re)allocations.
143	    allocator: std.mem.Allocator,
144	
145	    const Self = @This();
146	
147	    /// Allocate a zeroed buffer with at least `capacity` usable bytes.
148	    ///
149	    /// The actual allocation is rounded up to the nearest `ALIGNMENT` boundary.
150	    /// A capacity of 0 still allocates one alignment-unit so that the pointer
151	    /// is always valid and correctly aligned.
152	    pub fn init(allocator: std.mem.Allocator, capacity: usize) !Self {
153	        // Ensure a minimum of ALIGNMENT bytes so the pointer is never null.
154	        const actualCapacity = alignedSize(if (capacity == 0) ALIGNMENT else capacity);
155	
156	        const data = try allocator.alignedAlloc(u8, ALIGNMENT_VALUE, actualCapacity);
157	        // Zero-initialise the buffer so that uninitialised bytes are always valid to read.
158	        @memset(data, 0);
159	        return .{ .data = data, .allocator = allocator };
160	    }
161	
162	    /// Release resources owned by this instance.
163	    pub fn deinit(self: *Self) void {
164	        if (self.data.len == 0) return;
165	        self.allocator.free(self.data);
166	        self.data = empty_storage[0..];
167	    }
168	
169	    /// Return the logical length.
170	    pub fn len(self: Self) usize {
171	        return self.data.len;
172	    }
173	
174	    /// Return `true` when the logical length is zero.
175	    pub inline fn isEmpty(self: Self) bool {
176	        return self.data.len == 0;
177	    }
178	
179	    /// Transfer ownership to a new `SharedBuffer` and invalidate this buffer.
180	    ///
181	    /// `used` is the number of bytes to expose through the returned view;
182	    /// it must be ≤ `self.data.len`.  After the call `self.data` is reset to
183	    /// the empty sentinel — any previously held pointer into `self.data` must
184	    /// not be dereferenced.
185	    pub fn toShared(self: *Self, used: usize) !SharedBuffer {
186	        const storage = try self.allocator.create(BufferStorage);
187	        storage.* = .{
188	            .allocator = self.allocator,
189	            .data = self.data,
190	            .ref_count = std.atomic.Value(u32).init(1),
191	            .release_fn = BufferStorage.releaseDefault,
192	        };
193	        const shared = SharedBuffer{ .storage = storage, .data = self.data[0..used] };
194	        self.data = empty_storage[0..];
195	        return shared;
196	    }
