23	fn offsetValue(data: *const ArrayData, comptime T: type, i: usize) AccessorError![]const u8 {
24	    const base = try data.logicalIndex(i);
25	    const next = std.math.add(usize, base, 1) catch return error.InvalidOffsets;
26	    const offsets = try data.typedBufferAt(1, T);
27	    if (next >= offsets.len) return error.BufferTooSmall;
28	
29	    const start_raw = offsets[base];
30	    const end_raw = offsets[next];
31	    if (start_raw < 0 or end_raw < start_raw) return error.InvalidOffsets;
32	    const start = std.math.cast(usize, start_raw) orelse return error.InvalidOffsets;
33	    const end = std.math.cast(usize, end_raw) orelse return error.InvalidOffsets;
34	
35	    const values = try data.bufferAt(2);
36	    if (end > values.len()) return error.InvalidOffsets;
37	    return values.data[start..end];
38	}
