79	/// Builder for variable-length UTF-8 arrays.
80	pub const StringBuilder = struct {
81	    allocator: std.mem.Allocator,
82	    offsets: OwnedBuffer,
83	    data: OwnedBuffer,
84	    validity: ?OwnedBuffer = null,
85	    buffers: [3]SharedBuffer = undefined,
