90	
91	    /// Initialize and return a new instance.
92	    pub fn init(allocator: std.mem.Allocator, capacity: usize, data_capacity: usize) !StringBuilder {
93	        const offsets = try OwnedBuffer.init(allocator, (capacity + 1) * @sizeOf(i32));
94	        const offsets_slice = std.mem.bytesAsSlice(i32, offsets.data);
95	        offsets_slice[0] = 0;
96	        return .{
97	            .allocator = allocator,
98	            .offsets = offsets,
99	            .data = try OwnedBuffer.init(allocator, data_capacity),
100	        };
101	    }
102	
103	    /// Release resources owned by this instance.
104	    pub fn deinit(self: *StringBuilder) void {
105	        self.offsets.deinit();
106	        self.data.deinit();
107	        if (self.validity) |*valid| valid.deinit();
108	    }
109	
110	    /// Reset state while retaining reusable capacity when possible.
111	    pub fn reset(self: *StringBuilder) BuilderError!void {
112	        if (self.state != .finished) return BuilderError.NotFinished;
113	        if (!self.offsets.isEmpty()) {
114	            const offsets_slice = std.mem.bytesAsSlice(i32, self.offsets.data);
115	            offsets_slice[0] = 0;
116	        }
117	        self.len = 0;
118	        self.null_count = 0;
119	        self.data_len = 0;
120	        self.state = .ready;
121	    }
122	
123	    /// Clear state and release reusable buffers when required.
124	    pub fn clear(self: *StringBuilder) BuilderError!void {
125	        if (self.state != .finished) return BuilderError.NotFinished;
126	        self.offsets.deinit();
127	        self.data.deinit();
128	        if (self.validity) |*valid| valid.deinit();
129	        self.validity = null;
130	        self.len = 0;
131	        self.null_count = 0;
132	        self.data_len = 0;
133	        self.state = .ready;
134	    }
135	
136	    fn ensureOffsetsCapacity(self: *StringBuilder, needed_len: usize) !void {
137	        const capacity = self.offsets.len() / @sizeOf(i32);
138	        if (needed_len <= capacity) return;
139	        const was_empty = capacity == 0;
140	        try self.offsets.resize(needed_len * @sizeOf(i32));
141	        if (was_empty) {
142	            const offsets_slice = std.mem.bytesAsSlice(i32, self.offsets.data);
143	            offsets_slice[0] = 0;
144	        }
145	    }
146	
147	    fn ensureDataCapacity(self: *StringBuilder, needed_len: usize) !void {
148	        if (needed_len <= self.data.len()) return;
149	        try self.data.resize(needed_len);
150	    }
151	
152	    const BuilderError = error{ AlreadyFinished, NotFinished, OffsetOverflow };
153	
154	    /// Append one logical value into the builder.
155	    pub fn append(self: *StringBuilder, value: []const u8) !void {
156	        if (self.state == .finished) return BuilderError.AlreadyFinished;
157	        const next_len = self.len + 1;
158	        try self.ensureOffsetsCapacity(next_len + 1);
159	        try self.ensureDataCapacity(self.data_len + value.len);
160	        @memcpy(self.data.data[self.data_len .. self.data_len + value.len], value);
161	        self.data_len += value.len;
162	
163	        const cast_offset = std.math.cast(i32, self.data_len) orelse return BuilderError.OffsetOverflow;
164	        const offsets_slice = std.mem.bytesAsSlice(i32, self.offsets.data);
165	        offsets_slice[next_len] = cast_offset;
166	        try array_utils.setValidBit(&self.validity, self.len);
167	        self.len = next_len;
168	    }
169	
170	    /// Append a null entry into the builder.
171	    pub fn appendNull(self: *StringBuilder) !void {
172	        if (self.state == .finished) return BuilderError.AlreadyFinished;
173	        const next_len = self.len + 1;
174	        try self.ensureOffsetsCapacity(next_len + 1);
175	        const cast_offset = std.math.cast(i32, self.data_len) orelse return BuilderError.OffsetOverflow;
176	        const offsets_slice = std.mem.bytesAsSlice(i32, self.offsets.data);
177	        offsets_slice[next_len] = cast_offset;
178	        try array_utils.ensureValidityForNull(self.allocator, &self.validity, &self.null_count, next_len);
179	        self.len = next_len;
180	    }
181	
182	    /// Finalize builder state and return an immutable array reference.
183	    pub fn finish(self: *StringBuilder) !ArrayRef {
184	        if (self.state == .finished) return BuilderError.AlreadyFinished;
185	        const validity_buf = if (self.validity) |*buf| try buf.toShared(bitmap.byteLength(self.len)) else SharedBuffer.empty;
186	        self.buffers[0] = validity_buf;
187	        self.buffers[1] = try self.offsets.toShared((self.len + 1) * @sizeOf(i32));
188	        self.buffers[2] = try self.data.toShared(self.data_len);
189	
190	        const buffers = try self.allocator.alloc(SharedBuffer, 3);
191	        buffers[0] = self.buffers[0];
192	        buffers[1] = self.buffers[1];
193	        buffers[2] = self.buffers[2];
194	
195	        const data = ArrayData{
196	            .data_type = STRING_TYPE,
197	            .length = self.len,
198	            .null_count = self.null_count,
199	            .buffers = buffers,
200	        };
201	
202	        self.state = .finished;
203	        return ArrayRef.fromOwnedUnsafe(self.allocator, data);
204	    }
205	
206	    /// Finalize output and then reset builder state for reuse.
207	    pub fn finishReset(self: *StringBuilder) !ArrayRef {
208	        const finished_ref = try self.finish();
209	        try self.reset();
210	        return finished_ref;
211	    }
212	
213	    /// Finalize output and then clear builder state and buffers.
214	    pub fn finishClear(self: *StringBuilder) !ArrayRef {
215	        const finished_ref = try self.finish();
216	        try self.clear();
217	        return finished_ref;
218	    }
219	};
