277	                    var owned = buffers[i];
278	                    owned.release();
279	                }
280	                self.allocator.free(buffers);
281	            }
282	            buffers[0] = self.buffers[0];
283	            filled = 1;
284	            buffers[1] = self.buffers[1];
285	            filled = 2;
286	
287	            const children = try self.allocator.alloc(ArrayRef, 1);
288	            errdefer self.allocator.free(children);
