187	fn convertListToView(
188	    comptime OffsetT: type,
189	    allocator: std.mem.Allocator,
190	    base_ref: ArrayRef,
191	    dtype: DataType,
192	) !ArrayRef {
193	    const base = base_ref.data();
194	    std.debug.assert(base.buffers.len >= 2);
195	    std.debug.assert(base.children.len == 1);
196	
197	    const total_len = std.math.add(usize, base.offset, base.length) catch return error.InvalidOffsets;
198	    var sizes = try OwnedBuffer.init(allocator, total_len * @sizeOf(OffsetT));
199	    errdefer sizes.deinit();
200	
201	    const sizes_slice = std.mem.bytesAsSlice(OffsetT, sizes.data)[0..total_len];
202	    @memset(sizes_slice, 0);
203	    const offsets = try base.buffers[1].typedSlice(OffsetT);
204	    var i: usize = 0;
205	    while (i < base.length) : (i += 1) {
206	        const idx = base.offset + i;
207	        sizes_slice[idx] = offsets[idx + 1] - offsets[idx];
208	    }
209	
210	    var sizes_shared = try sizes.toShared(total_len * @sizeOf(OffsetT));
211	    errdefer sizes_shared.release();
212	
213	    const buffers = try allocator.alloc(SharedBuffer, 3);
214	    var filled_buffers: usize = 0;
215	    errdefer {
216	        var j: usize = 0;
217	        while (j < filled_buffers) : (j += 1) {
218	            var owned = buffers[j];
219	            owned.release();
220	        }
221	        allocator.free(buffers);
222	    }
223	    buffers[0] = base.buffers[0].retain();
224	    filled_buffers = 1;
225	    buffers[1] = base.buffers[1].retain();
226	    filled_buffers = 2;
227	    buffers[2] = sizes_shared;
228	    filled_buffers = 3;
229	    sizes_shared = SharedBuffer.empty;
230	
231	    const children = try allocator.alloc(ArrayRef, base.children.len);
232	    var filled_children: usize = 0;
233	    errdefer {
234	        var j: usize = 0;
235	        while (j < filled_children) : (j += 1) {
236	            var owned = children[j];
237	            owned.release();
238	        }
239	        allocator.free(children);
240	    }
241	    for (base.children, 0..) |child, idx| {
242	        children[idx] = child.retain();
243	        filled_children += 1;
244	    }
245	
246	    var dict_ref: ?ArrayRef = null;
247	    if (base.dictionary) |dict| dict_ref = dict.retain();
248	    errdefer if (dict_ref) |*owned| owned.release();
249	
250	    const out = ArrayData{
251	        .data_type = dtype,
252	        .length = base.length,
253	        .offset = base.offset,
254	        .null_count = base.null_count,
255	        .buffers = buffers,
256	        .children = children,
257	        .dictionary = dict_ref,
258	    };
259	    return ArrayRef.fromOwnedUnsafe(allocator, out);
260	}
