518	        if (children.len != self.union_type.fields.len) return BuilderError.InvalidChildCount;
519	        for (children, 0..) |child, i| {
520	            if (!std.meta.eql(child.data().data_type, self.union_type.fields[i].data_type.*)) return BuilderError.InvalidChildType;
521	        }
522	
523	        const offs = std.mem.bytesAsSlice(i32, self.offsets.data)[0..self.len];
524	        const type_ids = std.mem.bytesAsSlice(i8, self.type_ids.data)[0..self.len];
525	        for (type_ids, offs) |tid, off| {
526	            var child_idx: ?usize = null;
527	            for (self.union_type.type_ids, 0..) |id, idx| {
528	                if (id == tid) child_idx = idx;
529	            }
530	            const idx = child_idx orelse return BuilderError.InvalidTypeId;
531	            if (@as(usize, @intCast(off)) >= children[idx].data().length) return BuilderError.InvalidChildOffset;
532	        }
533	
534	        self.buffers[0] = try self.type_ids.toShared(self.len);
535	        self.buffers[1] = try self.offsets.toShared(self.len * @sizeOf(i32));
536	        const buffers = try self.allocator.alloc(SharedBuffer, 2);
537	        buffers[0] = self.buffers[0];
538	        buffers[1] = self.buffers[1];
539	
540	        const out_children = try self.allocator.alloc(ArrayRef, children.len);
541	        for (children, 0..) |child, i| out_children[i] = child.retain();
542	
543	        const data = ArrayData{
544	            .data_type = DataType{ .dense_union = self.union_type },
545	            .length = self.len,
546	            .buffers = buffers,
547	            .children = out_children,
